    /** Live monitoring screen shown while NOAA is active. */
    private void showNOAALiveMonitoringScreen(final Activity activity) {
        AlertDialog.Builder builder = new AlertDialog.Builder(activity);
        builder.setTitle("\uD83D\uDEF0\uFE0F NOAA APT — Live");

        LinearLayout layout = new LinearLayout(activity);
        layout.setOrientation(LinearLayout.VERTICAL);
        layout.setPadding(30, 30, 30, 30);

        // Timer text (top right, counts from first decoded line)
        noaaSignalStartTime = 0;
        noaaTimerText = new android.widget.TextView(activity);
        noaaTimerText.setText("⏱ Waiting...");
        noaaTimerText.setTextSize(14);
        noaaTimerText.setTextColor(0xFFFFAA00);
        noaaTimerText.setPadding(0, 0, 0, 4);
        layout.addView(noaaTimerText);

        // Progress text
        noaaProgressText = new android.widget.TextView(activity);
        noaaProgressText.setText("Calibrating sync...");
        noaaProgressText.setTextSize(14);
        noaaProgressText.setTextColor(0xFF00AAFF);
        noaaProgressText.setPadding(0, 0, 0, 15);
        layout.addView(noaaProgressText);

        // Live image view — FIT_XY fills the box so even a few decoded lines are visible
        noaaLiveImageView = new android.widget.ImageView(activity);
        int displayWidth = activity.getResources().getDisplayMetrics().widthPixels - 80;
        LinearLayout.LayoutParams imgParams = new LinearLayout.LayoutParams(
            displayWidth, displayWidth);   // square box; final APT image is ~1:1
        imgParams.bottomMargin = 15;
        noaaLiveImageView.setLayoutParams(imgParams);
        noaaLiveImageView.setScaleType(android.widget.ImageView.ScaleType.FIT_XY);
        noaaLiveImageView.setBackgroundColor(0xFF111111);
        layout.addView(noaaLiveImageView);

        // Info
        android.content.SharedPreferences prefs = activity.getSharedPreferences(
            "dmrmod_noaa_global", android.content.Context.MODE_PRIVATE);
        TextView infoText = new TextView(activity);
        infoText.setText("Frequency: "
            + prefs.getString("noaa_frequency", "137.100") + " MHz"
            + "\nLeft = Channel A (visible/IR)  |  Right = Channel B (thermal)");
        infoText.setTextSize(12);
        infoText.setTextColor(0xFF999999);
        layout.addView(infoText);

        // ========== SOFTWARE SQUELCH TOGGLE ==========
        final android.widget.ToggleButton noaaSoftSqToggle = new android.widget.ToggleButton(activity);
        noaaSoftSqToggle.setText("Soft SQ");
        noaaSoftSqToggle.setTextOn("🔇 Soft SQ: ON");
        noaaSoftSqToggle.setTextOff("🔊 Soft SQ: OFF");
        noaaSoftSqToggle.setChecked(isSoftwareSquelchEnabled);
        noaaSoftSqToggle.setTextSize(16);
        noaaSoftSqToggle.setAllCaps(false);
        noaaSoftSqToggle.setPadding(20, 20, 20, 20);
        LinearLayout.LayoutParams noaaToggleParams = new LinearLayout.LayoutParams(
            LinearLayout.LayoutParams.MATCH_PARENT,
            LinearLayout.LayoutParams.WRAP_CONTENT
        );
        noaaToggleParams.setMargins(0, 10, 0, 10);
        noaaSoftSqToggle.setLayoutParams(noaaToggleParams);

        android.graphics.drawable.StateListDrawable noaaToggleDrawable = new android.graphics.drawable.StateListDrawable();
        android.graphics.drawable.GradientDrawable noaaCheckedDrawable = new android.graphics.drawable.GradientDrawable();
        noaaCheckedDrawable.setShape(android.graphics.drawable.GradientDrawable.RECTANGLE);
        noaaCheckedDrawable.setColor(0xFF4CAF50);
        noaaCheckedDrawable.setCornerRadius(20 * activity.getResources().getDisplayMetrics().density);
        noaaCheckedDrawable.setStroke(
            (int) (2 * activity.getResources().getDisplayMetrics().density), 0xFFFFFFFF);
        noaaToggleDrawable.addState(new int[]{android.R.attr.state_checked}, noaaCheckedDrawable);
        android.graphics.drawable.GradientDrawable noaaUncheckedDrawable = new android.graphics.drawable.GradientDrawable();
        noaaUncheckedDrawable.setShape(android.graphics.drawable.GradientDrawable.RECTANGLE);
        noaaUncheckedDrawable.setColor(0xFF666666);
        noaaUncheckedDrawable.setCornerRadius(20 * activity.getResources().getDisplayMetrics().density);
        noaaUncheckedDrawable.setStroke(
            (int) (2 * activity.getResources().getDisplayMetrics().density), 0x80FFFFFF);
        noaaToggleDrawable.addState(new int[]{}, noaaUncheckedDrawable);
        noaaSoftSqToggle.setBackground(noaaToggleDrawable);
        layout.addView(noaaSoftSqToggle);

        // ========== SOFTWARE SQUELCH SLIDER ==========
        final LinearLayout noaaSqContainer = new LinearLayout(activity);
        noaaSqContainer.setOrientation(LinearLayout.HORIZONTAL);
        noaaSqContainer.setPadding(0, 0, 0, 10);
        noaaSqContainer.setLayoutParams(new LinearLayout.LayoutParams(
            LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT));
        noaaSqContainer.setVisibility(isSoftwareSquelchEnabled ? View.VISIBLE : View.GONE);

        TextView noaaSqLabel = new TextView(activity);
        noaaSqLabel.setText("SQ:");
        noaaSqLabel.setTextColor(0xFFFFFFFF);
        noaaSqLabel.setTextSize(14);
        noaaSqLabel.setTypeface(null, android.graphics.Typeface.BOLD);
        LinearLayout.LayoutParams noaaSqLabelParams = new LinearLayout.LayoutParams(
            LinearLayout.LayoutParams.WRAP_CONTENT, LinearLayout.LayoutParams.WRAP_CONTENT);
        noaaSqLabelParams.gravity = android.view.Gravity.CENTER_VERTICAL;
        noaaSqLabelParams.rightMargin = (int) (6 * activity.getResources().getDisplayMetrics().density);
        noaaSqLabel.setLayoutParams(noaaSqLabelParams);
        noaaSqContainer.addView(noaaSqLabel);

        final TextView noaaSqValueLabel = new TextView(activity);
        noaaSqValueLabel.setText(String.valueOf(softwareSquelchThreshold));
        noaaSqValueLabel.setTextColor(0xFF00FF00);
        noaaSqValueLabel.setTextSize(18);
        noaaSqValueLabel.setTypeface(null, android.graphics.Typeface.BOLD);
        noaaSqValueLabel.setGravity(android.view.Gravity.CENTER);
        LinearLayout.LayoutParams noaaSqValueParams = new LinearLayout.LayoutParams(
            (int) (40 * activity.getResources().getDisplayMetrics().density),
            LinearLayout.LayoutParams.WRAP_CONTENT);
        noaaSqValueParams.gravity = android.view.Gravity.CENTER_VERTICAL;
        noaaSqValueLabel.setLayoutParams(noaaSqValueParams);
        noaaSqContainer.addView(noaaSqValueLabel);

        final android.widget.SeekBar noaaSqSeekBar = new android.widget.SeekBar(activity);
        LinearLayout.LayoutParams noaaSqSeekParams = new LinearLayout.LayoutParams(
            0, LinearLayout.LayoutParams.WRAP_CONTENT);
        noaaSqSeekParams.weight = 1.0f;
        noaaSqSeekParams.topMargin = (int) (4 * activity.getResources().getDisplayMetrics().density);
        noaaSqSeekParams.leftMargin = (int) (10 * activity.getResources().getDisplayMetrics().density);
        noaaSqSeekBar.setLayoutParams(noaaSqSeekParams);
        noaaSqSeekBar.setMax(9);
        noaaSqSeekBar.setProgress(softwareSquelchThreshold);
        try {
            android.content.res.ColorStateList blackColor = android.content.res.ColorStateList.valueOf(0xFF000000);
            noaaSqSeekBar.setProgressTintList(blackColor);
            noaaSqSeekBar.setProgressBackgroundTintList(blackColor);
            noaaSqSeekBar.setThumbTintList(blackColor);
        } catch (Exception e) {
            XposedBridge.log(TAG + ": Could not set NOAA squelch slider color: " + e);
        }
        noaaSqSeekBar.setOnSeekBarChangeListener(new android.widget.SeekBar.OnSeekBarChangeListener() {
            @Override
            public void onProgressChanged(android.widget.SeekBar seekBar, int progress, boolean fromUser) {
                if (fromUser) {
                    noaaSqValueLabel.setText(String.valueOf(progress));
                    softwareSquelchThreshold = progress;
                }
            }
            @Override public void onStartTrackingTouch(android.widget.SeekBar seekBar) { }
            @Override
            public void onStopTrackingTouch(android.widget.SeekBar seekBar) {
                Toast.makeText(activity, "Software Squelch: " + seekBar.getProgress(), Toast.LENGTH_SHORT).show();
                XposedBridge.log(TAG + ": NOAA squelch level set to " + seekBar.getProgress());
            }
        });
        noaaSqContainer.addView(noaaSqSeekBar);
        layout.addView(noaaSqContainer);

        final TextView noaaSqInfo = new TextView(activity);
        noaaSqInfo.setText("📊 Hybrid RSSI + Audio RMS squelch\n0=most sensitive, 9=least sensitive");
        noaaSqInfo.setTextSize(11);
        noaaSqInfo.setTextColor(0xFF999999);
        noaaSqInfo.setPadding(0, 0, 0, 10);
        noaaSqInfo.setVisibility(isSoftwareSquelchEnabled ? View.VISIBLE : View.GONE);
        layout.addView(noaaSqInfo);

        noaaSoftSqToggle.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                isSoftwareSquelchEnabled = noaaSoftSqToggle.isChecked();
                if (isSoftwareSquelchEnabled) {
                    enableSoftwareSquelchOnCurrentChannel();
                    Toast.makeText(activity, "NOAA software squelch enabled", Toast.LENGTH_SHORT).show();
                    noaaSqContainer.setVisibility(View.VISIBLE);
                    noaaSqInfo.setVisibility(View.VISIBLE);
                    new android.os.Handler(android.os.Looper.getMainLooper()).postDelayed(new Runnable() {
                        @Override public void run() {
                            if (isSoftwareSquelchEnabled) enableSoftwareSquelchOnCurrentChannel();
                        }
                    }, 2500);
                } else {
                    disableSoftwareSquelchOnCurrentChannel();
                    Toast.makeText(activity, "NOAA hardware squelch enabled", Toast.LENGTH_SHORT).show();
                    noaaSqContainer.setVisibility(View.GONE);
                    noaaSqInfo.setVisibility(View.GONE);
                }
            }
        });

        // Color mode toggle button
        noaaColorModeButton = new android.widget.Button(activity);
        noaaColorModeButton.setText("🎸 Gray");
        noaaColorModeButton.setTextSize(13);
        LinearLayout.LayoutParams btnParams = new LinearLayout.LayoutParams(
            LinearLayout.LayoutParams.MATCH_PARENT,
            LinearLayout.LayoutParams.WRAP_CONTENT);
        btnParams.topMargin = 10;
        noaaColorModeButton.setLayoutParams(btnParams);
        noaaColorModeButton.setOnClickListener(v -> {
            if (noaaReceiver == null) return;
            int next = (noaaReceiver.getColorMode() + 1) % 3;
            noaaReceiver.setColorMode(next);
            switch (next) {
                case NOAAReceiver.COLOR_GRAY:    noaaColorModeButton.setText("🎸 Gray");           break;
                case NOAAReceiver.COLOR_THERMAL: noaaColorModeButton.setText("🌡️ Thermal IR");      break;
                case NOAAReceiver.COLOR_MSA:     noaaColorModeButton.setText("🌈 Color (MSA)");       break;
            }
            // Force immediate redraw with new color mode
            Bitmap snap = noaaReceiver.getLiveBitmap();
            if (snap != null && noaaLiveImageView != null) noaaLiveImageView.setImageBitmap(snap);
        });
        layout.addView(noaaColorModeButton);

        builder.setView(layout);
        builder.setNegativeButton("Stop", (d, w) -> stopNOAAMonitoring(activity));
        builder.setNeutralButton("Save Now", (d, w) -> {
            if (noaaReceiver != null) {
                String path = noaaReceiver.saveFinalImage();
                Toast.makeText(activity,
                    path != null ? "Saved: " + path : "No image yet", Toast.LENGTH_LONG).show();
            }
        });
        builder.setCancelable(false);

        noaaMonitoringDialog = builder.create();
        noaaMonitoringDialog.show();

        // Periodic UI update every 2 seconds
        noaaUpdateHandler  = new android.os.Handler(android.os.Looper.getMainLooper());
        noaaUpdateRunnable = new Runnable() {
            @Override public void run() {
                if (isNOAAMonitoringActive) {
                    updateNOAALiveScreen();
                    noaaUpdateHandler.postDelayed(this, 2000);
                }
            }
        };
        noaaUpdateHandler.postDelayed(noaaUpdateRunnable, 2000);
    }

    /** Refresh the live image and progress text. */
    private void updateNOAALiveScreen() {
        if (noaaReceiver == null) return;
        try {
            if (noaaTimerText != null) {
                if (noaaSignalStartTime > 0) {
                    long elapsed = (System.currentTimeMillis() - noaaSignalStartTime) / 1000;
                    long h = elapsed / 3600;
                    long m = (elapsed % 3600) / 60;
                    long s = elapsed % 60;
                    String ts = h > 0
                        ? String.format(java.util.Locale.US, "\u23f1 %d:%02d:%02d", h, m, s)
                        : String.format(java.util.Locale.US, "\u23f1 %d:%02d", m, s);
                    noaaTimerText.setText(ts);
                    noaaTimerText.setTextColor(0xFF00CC44);
                } else {
                    noaaTimerText.setText("\u23f1 Waiting for signal...");
                    noaaTimerText.setTextColor(0xFFFFAA00);
                }
            }
            if (noaaProgressText != null) {
                int lines = noaaReceiver.getDecodedLines();
                noaaProgressText.setText(noaaReceiver.getStatus()
                    + (lines > 0 ? "  (" + lines + " lines \u2248 " + (lines / 2) + " sec)" : "")
                    + (noaaDopplerStatus.isEmpty() ? "" : "\n" + noaaDopplerStatus));
            }
            if (noaaLiveImageView != null) {
                Bitmap snap = noaaReceiver.getLiveBitmap();
                if (snap != null) noaaLiveImageView.setImageBitmap(snap);
            }
        } catch (Exception e) {
            XposedBridge.log(TAG + ": updateNOAALiveScreen error: " + e.getMessage());
        }
    }

    /** Settings dialog for NOAA frequency etc. */
    private void showNOAASettingsDialog(final Activity activity) {
        showNOAASettingsDialog(activity, null);
    }

    private void showNOAASettingsDialog(final Activity activity, final Runnable onSaved) {
        AlertDialog.Builder builder = new AlertDialog.Builder(activity);
        builder.setTitle("\u2699\uFE0F NOAA APT Settings");

        LinearLayout layout = new LinearLayout(activity);
        layout.setOrientation(LinearLayout.VERTICAL);
        layout.setPadding(40, 40, 40, 40);

        android.content.SharedPreferences prefs = activity.getSharedPreferences(
            "dmrmod_noaa_global", android.content.Context.MODE_PRIVATE);

        TextView freqLabel = new TextView(activity);
        freqLabel.setText("NOAA Satellite Frequency (MHz):");
        freqLabel.setTextSize(14);
        freqLabel.setPadding(0, 10, 0, 5);
        layout.addView(freqLabel);

        final EditText freqEdit = new EditText(activity);
        freqEdit.setText(prefs.getString("noaa_frequency", "137.100"));
        freqEdit.setInputType(android.text.InputType.TYPE_CLASS_NUMBER
            | android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);
        layout.addView(freqEdit);

        TextView infoText = new TextView(activity);
        infoText.setText("\nSatellite frequencies:\n"
            + "\u2022 NOAA-19  137.100 MHz  (recommended, most active)\n"
            + "\u2022 NOAA-15  137.620 MHz\n"
            + "\u2022 NOAA-18  137.9125 MHz\n\n"
            + "Images are saved automatically to:\nDownload/DMR/NOAA/");
        infoText.setTextSize(13);
        infoText.setTextColor(0xFF999999);
        layout.addView(infoText);

        builder.setView(new android.widget.ScrollView(activity) {{ addView(layout); }});
        builder.setPositiveButton("Save", (d, w) -> {
            String freqStr = freqEdit.getText().toString().trim();
            try {
                double f = Double.parseDouble(freqStr);
                if (f < 100 || f > 180) {
                    Toast.makeText(activity, "Frequency out of VHF range (100-180 MHz)",
                        Toast.LENGTH_SHORT).show();
                    return;
                }
                prefs.edit().putString("noaa_frequency", freqStr).apply();
                Toast.makeText(activity, "NOAA settings saved", Toast.LENGTH_SHORT).show();
                if (onSaved != null) onSaved.run();
            } catch (NumberFormatException e) {
                Toast.makeText(activity, "Invalid frequency format", Toast.LENGTH_SHORT).show();
            }
        });
        builder.setNegativeButton("Cancel", null);
        builder.create().show();
    }

    /** Show upcoming NOAA satellite passes based on GPS location. */
    private void showNOAANextPassesDialog(final Activity activity) {
        // Show a "Calculating..." dialog immediately, then compute on background thread
        AlertDialog.Builder loadingBuilder = new AlertDialog.Builder(activity);
        loadingBuilder.setTitle("\uD83D\uDCC5 Next Satellite Passes");
        TextView loadingText = new TextView(activity);
        loadingText.setText("Getting GPS location and calculating passes...\n\nThis may take a few seconds.");
        loadingText.setPadding(60, 40, 60, 40);
        loadingText.setTextSize(14);
        loadingBuilder.setView(loadingText);
        loadingBuilder.setCancelable(true);
        loadingBuilder.setNegativeButton("Cancel", null);
        AlertDialog loadingDialog = loadingBuilder.create();
        loadingDialog.show();

        // Fetch fresh TLEs + compute passes on background thread
        new Thread(() -> {
            try {
                // Try refreshing TLEs first (non-blocking if it fails)
                try { SatellitePassPredictor.fetchFreshTles(); } catch (Exception ignored) {}

                // Get GPS
                android.location.Location loc = SatellitePassPredictor.getLastLocation(activity);
                final double lat, lon, alt;
                final String locStr;
                if (loc != null) {
                    lat = loc.getLatitude();
                    lon = loc.getLongitude();
                    alt = loc.getAltitude();
                    locStr = String.format(java.util.Locale.US, "%.4f°, %.4f°  alt=%.0fm",
                        lat, lon, alt);
                } else {
                    // Fallback: use a default if GPS unavailable
                    lat = 0; lon = 0; alt = 0;
                    locStr = "GPS unavailable — showing passes for 0°,0° (equator)";
                }

                final java.util.List<SatellitePassPredictor.Pass> passes =
                    SatellitePassPredictor.findPasses(lat, lon, alt, 3, 5.0);

                activity.runOnUiThread(() -> {
                    if (!loadingDialog.isShowing()) return;
                    loadingDialog.dismiss();
                    showNOAAPassListDialog(activity, passes, locStr);
                });

            } catch (Exception e) {
                XposedBridge.log(TAG + ": showNOAANextPassesDialog error: " + e);
                activity.runOnUiThread(() -> {
                    loadingDialog.dismiss();
                    Toast.makeText(activity, "Error: " + e.getMessage(), Toast.LENGTH_LONG).show();
                });
            }
        }).start();
    }

    /** Render the pass list dialog once results are ready. */
    private void showNOAAPassListDialog(final Activity activity,
                                         final java.util.List<SatellitePassPredictor.Pass> passes,
                                         final String locStr) {
        AlertDialog.Builder builder = new AlertDialog.Builder(activity);
        builder.setTitle("\uD83D\uDCC5 Next Satellite Passes");

        android.widget.ScrollView scroll = new android.widget.ScrollView(activity);
        LinearLayout layout = new LinearLayout(activity);
        layout.setOrientation(LinearLayout.VERTICAL);
        layout.setPadding(30, 30, 30, 20);
        scroll.addView(layout);

        // Location info
        TextView locView = new TextView(activity);
        locView.setText("\uD83D\uDCCD " + locStr);
        locView.setTextSize(12);
        locView.setTextColor(0xFF888888);
        locView.setPadding(0, 0, 0, 16);
        layout.addView(locView);

        if (passes == null || passes.isEmpty()) {
            TextView empty = new TextView(activity);
            empty.setText("No passes above 5° elevation in the next 3 days.\n\n"
                + "This may indicate stale TLE data or a GPS issue.\n\n"
                + "Expected approximate passes per day:\n"
                + "\u2022 NOAA-19  ~14\n"
                + "\u2022 NOAA-18  ~14\n"
                + "\u2022 NOAA-15  ~14\n\n"
                + "Passes with elevation < 5° are filtered out.");
            empty.setTextSize(13);
            empty.setTextColor(0xFF999999);
            empty.setPadding(0, 10, 0, 10);
            layout.addView(empty);
        } else {
            // Column headers
            android.widget.TableLayout table = new android.widget.TableLayout(activity);
            table.setStretchAllColumns(true);
            addPassTableHeader(table, activity);

            String lastDate = "";
            for (SatellitePassPredictor.Pass pass : passes) {
                String date = pass.getDateString();
                if (!date.equals(lastDate)) {
                    // Date separator
                    android.widget.TableRow sep = new android.widget.TableRow(activity);
                    TextView dateLabel = new TextView(activity);
                    dateLabel.setText("── " + date + " UTC ──");
                    dateLabel.setTextSize(11);
                    dateLabel.setTextColor(0xFF5599AA);
                    dateLabel.setPadding(4, 14, 4, 4);
                    android.widget.TableRow.LayoutParams spanParams =
                        new android.widget.TableRow.LayoutParams();
                    spanParams.span = 5;
                    sep.addView(dateLabel, spanParams);
                    table.addView(sep);
                    lastDate = date;
                }
                addPassTableRow(table, activity, pass);
            }
            layout.addView(table);

            TextView hint = new TextView(activity);
            hint.setText("\nTimes are UTC  \u2022  Elevations <5° filtered  \u2022  "
                + "Tap \"Start Mon\" to listen at AOS");
            hint.setTextSize(11);
            hint.setTextColor(0xFF666666);
            hint.setPadding(0, 12, 0, 0);
            layout.addView(hint);
        }

        builder.setView(scroll);
        builder.setPositiveButton("Close", null);
        builder.create().show();
    }

    private void addPassTableHeader(android.widget.TableLayout table, Activity activity) {
        android.widget.TableRow row = new android.widget.TableRow(activity);
        String[] cols = {"Satellite", "AOS (UTC)", "Max El", "LOS (UTC)", "Dur"};
        for (String col : cols) {
            TextView tv = new TextView(activity);
            tv.setText(col);
            tv.setTextSize(11);
            tv.setTextColor(0xFF00AACC);
            tv.setTypeface(android.graphics.Typeface.DEFAULT_BOLD);
            tv.setPadding(4, 4, 4, 8);
            row.addView(tv);
        }
        table.addView(row);
    }

    private void addPassTableRow(android.widget.TableLayout table, Activity activity,
                                  SatellitePassPredictor.Pass pass) {
        android.widget.TableRow row = new android.widget.TableRow(activity);
        java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("HH:mm:ss",
            java.util.Locale.US);
        sdf.setTimeZone(java.util.TimeZone.getTimeZone("UTC"));

        String[] cells = {
            pass.name,
            sdf.format(new java.util.Date(pass.aosMs)),
            String.format(java.util.Locale.US, "%.0f°", pass.maxElDeg),
            sdf.format(new java.util.Date(pass.losMs)),
            (pass.durationSec / 60) + "m" + String.format("%02d", pass.durationSec % 60) + "s"
        };

        // Colour-code by max elevation
        int elColor;
        if      (pass.maxElDeg >= 60) elColor = 0xFF00FF88;   // excellent
        else if (pass.maxElDeg >= 30) elColor = 0xFF88FF44;   // good
        else if (pass.maxElDeg >= 15) elColor = 0xFFFFCC00;   // fair
        else                          elColor = 0xFFAAAAAA;   // low

        for (int i = 0; i < cells.length; i++) {
            TextView tv = new TextView(activity);
            tv.setText(cells[i]);
            tv.setTextSize(12);
            tv.setTextColor(i == 2 ? elColor : 0xFFDDDDDD);
            tv.setPadding(4, 6, 4, 6);
            row.addView(tv);
        }
        table.addView(row);
    }

    /** Browse saved NOAA images. */
    private void showNOAAReceivedImagesDialog(final Activity activity) {
        AlertDialog.Builder builder = new AlertDialog.Builder(activity);
        builder.setTitle("\uD83D\uDDBC\uFE0F Saved NOAA Images");

        java.io.File dir = new java.io.File(
            android.os.Environment.getExternalStoragePublicDirectory(
                android.os.Environment.DIRECTORY_DOWNLOADS),
            "DMR/NOAA");

        android.widget.ScrollView scroll = new android.widget.ScrollView(activity);
        LinearLayout layout = new LinearLayout(activity);
        layout.setOrientation(LinearLayout.VERTICAL);
        layout.setPadding(30, 30, 30, 30);
        scroll.addView(layout);

        java.io.File[] files = dir.isDirectory() ? dir.listFiles() : null;

        if (files == null || files.length == 0) {
            TextView empty = new TextView(activity);
            empty.setText("No saved images yet.\n\nImages are auto-saved every 300 decoded lines"
                + " (~5 min) to:\nDownload/DMR/NOAA/");
            empty.setTextSize(14);
            empty.setPadding(0, 20, 0, 20);
            layout.addView(empty);
        } else {
            java.util.Arrays.sort(files, (a, b) -> Long.compare(b.lastModified(), a.lastModified()));
            for (java.io.File f : files) {
                if (!f.getName().endsWith(".png")) continue;
                android.widget.Button btn = new android.widget.Button(activity);
                btn.setText("\uD83D\uDDBC\uFE0F " + f.getName()
                    + "  (" + (f.length() / 1024) + " KB)");
                btn.setAllCaps(false);
                btn.setTextSize(13);
                final java.io.File file = f;
                btn.setOnClickListener(v -> {
                    try {
                        android.content.Intent intent = new android.content.Intent(
                            android.content.Intent.ACTION_VIEW);
                        android.net.Uri uri = android.net.Uri.fromFile(file);
                        intent.setDataAndType(uri, "image/png");
                        intent.addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK);
                        activity.startActivity(intent);
                    } catch (Exception e) {
                        Toast.makeText(activity, "Cannot open image: " + e.getMessage(),
                            Toast.LENGTH_SHORT).show();
                    }
                });
                layout.addView(btn);
            }
        }

        builder.setView(scroll);
        builder.setPositiveButton("Close", null);
        builder.create().show();
    }

    /** Start NOAA monitoring: hijack channel to NOAA frequency, init receiver. */
    private void startNOAAMonitoring(final Activity activity) {
        try {
            XposedBridge.log(TAG + ": Starting NOAA APT monitoring");

            // Stop conflicting modes
            if (isAPRSMonitoringActive)  stopAPRSMonitoring(activity);
            if (isSSTVMonitoringActive)  stopSSTVMonitoring(activity);

            Class<?> dmrManagerClass = XposedHelpers.findClass(
                "com.pri.prizeinterphone.manager.DmrManager", appClassLoader);
            Object dmrManager = XposedHelpers.callStaticMethod(dmrManagerClass, "getInstance");
            Object channel    = XposedHelpers.callMethod(dmrManager, "getCurrentChannel");
            if (channel == null) throw new Exception("Cannot get current channel");

            // Back up original channel
            saveNOAAChannelBackup(channel);

            // Determine target frequency
            android.content.SharedPreferences prefs = activity.getSharedPreferences(
                "dmrmod_noaa_global", android.content.Context.MODE_PRIVATE);
            String freqStr = prefs.getString("noaa_frequency", "137.100");
            int freqHz;
            try {
                freqHz = (int) (Double.parseDouble(freqStr) * 1_000_000);
            } catch (NumberFormatException e) {
                freqHz = 137_100_000;
            }

            // Hijack channel with NOAA settings
            String origName = (String) noaaChannelBackup.get("name");
            if (origName == null || origName.isEmpty()) origName = "Channel";
            XposedHelpers.setIntField(channel, "type",   1);    // ANALOG
            XposedHelpers.setObjectField(channel, "name", "NOAA (" + origName + ")");
            XposedHelpers.setIntField(channel, "rxFreq", freqHz);
            XposedHelpers.setIntField(channel, "txFreq", freqHz);
            XposedHelpers.setIntField(channel, "sq",     2);  // sq=2 (0 kills audio on this hardware)
            // channel_band is BANDWIDTH: NOAA weather radio is wide FM (25 kHz) (backlog R1).
            // channelMode is a digital-only field and is not written for analog.
            XposedHelpers.setIntField(channel, "band",   1);
            XposedHelpers.setIntField(channel, "power",  1);
            XposedHelpers.setIntField(channel, "rxType", 0);
            XposedHelpers.setIntField(channel, "rxSubCode", 0);
            XposedHelpers.setIntField(channel, "txType", 0);
            XposedHelpers.setIntField(channel, "txSubCode", 0);

            // Hardware ONLY (no updateChannel): same reasoning as SSTV — persisting the hijack to the
            // channel DB leaves the user's channel clobbered if the restore is ever skipped. The
            // in-memory override reverts on the next channel reload.
            XposedHelpers.callMethod(dmrManager, "syncChannelInfoWithData", channel);

            noaaBaseFreqHz = freqHz;
            noaaAppliedOffsetHz = 0;
            noaaDopplerEnabled = prefs.getBoolean("noaa_doppler", true);
            startNoaaDopplerTracking(activity);

            // Init NOAA receiver
            noaaReceiver = NOAAReceiver.getInstance(activity);
            noaaReceiver.reset();

            noaaReceiver.setLineDecodeCallback((lineNum, snap) -> {
                activity.runOnUiThread(() -> {
                    try {
                        // Record the moment the first line arrives (signal confirmed)
                        if (noaaSignalStartTime == 0) {
                            noaaSignalStartTime = System.currentTimeMillis();
                        }
                        if (noaaLiveImageView != null && snap != null) {
                            noaaLiveImageView.setImageBitmap(snap);
                        }
                        if (noaaProgressText != null) {
                            noaaProgressText.setText("Decoding — " + lineNum + " lines  ("
                                + (lineNum / 2) + " sec)");
                            noaaProgressText.setTextColor(0xFF00AAFF);
                        }
                    } catch (Exception e) {
                        XposedBridge.log(TAG + ": NOAA line callback error: " + e);
                    }
                });
            });

            noaaReceiver.setImageSavedCallback((path, totalLines) ->
                activity.runOnUiThread(() ->
                    Toast.makeText(activity,
                        "\uD83D\uDEF0\uFE0F NOAA: saved " + totalLines + " lines → " + path,
                        Toast.LENGTH_LONG).show()));

            isNOAAMonitoringActive = true;
            currentChannelType = 1;  // Analog

            XposedBridge.log(TAG + ": NOAA monitoring active at " + freqStr + " MHz");
            Toast.makeText(activity, "NOAA Monitoring Active at " + freqStr + " MHz",
                Toast.LENGTH_SHORT).show();

        } catch (Exception e) {
            XposedBridge.log(TAG + ": Error starting NOAA monitoring: " + e.getMessage());
            XposedBridge.log(e);
            Toast.makeText(activity, "Error: " + e.getMessage(), Toast.LENGTH_LONG).show();
        }
    }

    /** Stop NOAA monitoring and restore original channel. */
    private void stopNOAAMonitoring(final Activity activity) {
        try {
            XposedBridge.log(TAG + ": Stopping NOAA monitoring");

            if (noaaReceiver != null) {
                noaaReceiver.saveFinalImage();
                noaaReceiver.stop();
            }

            // Dismiss dialog
            if (noaaMonitoringDialog != null && noaaMonitoringDialog.isShowing()) {
                noaaMonitoringDialog.dismiss();
            }
            noaaMonitoringDialog  = null;
            noaaLiveImageView     = null;
            noaaProgressText      = null;
            noaaColorModeButton   = null;

            // Cancel update handler
            if (noaaUpdateHandler != null && noaaUpdateRunnable != null) {
                noaaUpdateHandler.removeCallbacks(noaaUpdateRunnable);
            }
            noaaUpdateHandler  = null;
            noaaUpdateRunnable = null;

            isNOAAMonitoringActive = false;
            stopNoaaDopplerTracking();

            if (isSoftwareSquelchEnabled) {
                isSoftwareSquelchEnabled = false;
                disableSoftwareSquelchOnCurrentChannel();
            }

            restoreNOAAChannelBackup(activity);

            Toast.makeText(activity, "NOAA Monitoring Stopped", Toast.LENGTH_SHORT).show();
            XposedBridge.log(TAG + ": NOAA monitoring stopped");

        } catch (Exception e) {
            XposedBridge.log(TAG + ": Error stopping NOAA monitoring: " + e.getMessage());
        }
    }

    // -----------------------------------------------------------------------
    // NOAA Weather Radio SAME alerts (F8)
    // -----------------------------------------------------------------------

    private void showWxAlertsDialog(final Activity activity) {
        try {
            final android.content.SharedPreferences prefs = activity.getSharedPreferences("dmrmod_wx", android.content.Context.MODE_PRIVATE);
            AlertDialog.Builder builder = new AlertDialog.Builder(activity);
            builder.setTitle("\u26C8\uFE0F NOAA Weather Alerts (SAME)");
            LinearLayout layout = new LinearLayout(activity);
            layout.setOrientation(LinearLayout.VERTICAL);
            layout.setPadding(40, 30, 40, 10);

            final TextView status = new TextView(activity);
            status.setTextSize(14);
            status.setText(isWxMonitoringActive ? ("\uD83D\uDFE2 Listening " + wxStatus) : "\u26AB Not listening");
            status.setTextColor(isWxMonitoringActive ? 0xFF69F0AE : 0xFFBBBBBB);
            layout.addView(status);

            TextView note = new TextView(activity);
            note.setText("Decodes the digital SAME headers NOAA Weather Radio sends before every warning, "
                    + "watch and test (Specific Area Message Encoding, 520.8 baud AFSK), plus the 1050 Hz "
                    + "attention tone and the NNNN end-of-message. Alerts are listed here and raised as "
                    + "notifications. The radio is parked on the chosen WX channel until you stop.");
            note.setTextSize(12); note.setTextColor(0xFF999999); note.setPadding(0, 10, 0, 10);
            layout.addView(note);

            TextView chLabel = new TextView(activity);
            chLabel.setText("Listen on:"); chLabel.setTextSize(13);
            layout.addView(chLabel);
            final android.widget.Spinner chSpin = new android.widget.Spinner(activity);
            String[] items = new String[WX_NAMES.length + 1];
            System.arraycopy(WX_NAMES, 0, items, 0, WX_NAMES.length);
            items[WX_NAMES.length] = "Current channel (no retune)";
            android.widget.ArrayAdapter<String> ad = new android.widget.ArrayAdapter<String>(activity, android.R.layout.simple_spinner_item, items);
            ad.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);
            chSpin.setAdapter(ad);
            chSpin.setSelection(prefs.getInt("wx_channel", 4));
            layout.addView(chSpin);

            TextView histLabel = new TextView(activity);
            histLabel.setText("\nRecent alerts:"); histLabel.setTextSize(13);
            layout.addView(histLabel);
            final TextView hist = new TextView(activity);
            hist.setTextSize(12); hist.setTextColor(0xFFCCCCCC);
            hist.setText(wxHistoryText(prefs));
            android.widget.ScrollView sv = new android.widget.ScrollView(activity);
            sv.addView(hist);
            sv.setLayoutParams(new LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT,
                    (int) (160 * activity.getResources().getDisplayMetrics().density)));
            layout.addView(sv);

            builder.setView(layout);
            builder.setPositiveButton(isWxMonitoringActive ? "Stop" : "Start", new DialogInterface.OnClickListener() {
                @Override public void onClick(DialogInterface d, int w) {
                    if (isWxMonitoringActive) { stopWxMonitoring(activity); return; }
                    int sel = chSpin.getSelectedItemPosition();
                    prefs.edit().putInt("wx_channel", sel).apply();
                    startWxMonitoring(activity, sel < WX_FREQS.length ? WX_FREQS[sel] : -1);
                }
            });
            builder.setNeutralButton("Clear list", new DialogInterface.OnClickListener() {
                @Override public void onClick(DialogInterface d, int w) { prefs.edit().remove("alerts").apply(); }
            });
            builder.setNegativeButton("Close", null);
            builder.show();
        } catch (Throwable t) {
            XposedBridge.log(TAG + ": [wx] dialog error: " + t.getMessage());
        }
    }

    private static String wxHistoryText(android.content.SharedPreferences prefs) {
        try {
            org.json.JSONArray arr = new org.json.JSONArray(prefs.getString("alerts", "[]"));
            if (arr.length() == 0) return "(none yet)";
            StringBuilder sb = new StringBuilder();
            java.text.SimpleDateFormat df = new java.text.SimpleDateFormat("MM-dd HH:mm", java.util.Locale.US);
            for (int i = arr.length() - 1; i >= 0; i--) {
                org.json.JSONObject o = arr.getJSONObject(i);
                sb.append(df.format(new java.util.Date(o.optLong("t")))).append("  ").append(o.optString("summary")).append("\n")
                  .append("    ").append(o.optString("raw")).append("\n");
            }
            return sb.toString();
        } catch (Throwable t) { return "(unreadable)"; }
    }

    private void startWxMonitoring(final Activity activity, int freqHz) { startWxMonitoring(activity, freqHz, -1); }

    private void startWxMonitoring(final Activity activity, int freqHz, int band) {
        try {
            if (isAPRSMonitoringActive) stopAPRSMonitoring(activity);
            if (isSSTVMonitoringActive) stopSSTVMonitoring(activity);
            if (isNOAAMonitoringActive) stopNOAAMonitoring(activity);
            if (kissActive) stopKissTnc();
            final android.content.Context appCtx = activity.getApplicationContext();
            if (freqHz > 0) {
                captureTxFreqBackup();
                tuneCurrentChannelAnalog(freqHz, -1, band);
                wxTuned = true;
                wxStatus = "on " + (freqHz / 1e6) + " MHz";
            } else {
                wxTuned = false;
                wxStatus = "on the current channel";
            }
            wxDecoder = new SAMEDecoder(8000, true, new SAMEDecoder.Listener() {
                @Override public void onMessage(final SAMEDecoder.Message m) {
                    wxStoreAlert(appCtx, m);
                    if (!m.eom) wxNotify(appCtx, m);
                    final String text = m.eom ? "\u26C8\uFE0F Weather alert: end of message" : ("\u26C8\uFE0F " + m.summary());
                    new android.os.Handler(android.os.Looper.getMainLooper()).post(new Runnable() {
                        @Override public void run() { try { Toast.makeText(appCtx, text, Toast.LENGTH_LONG).show(); } catch (Throwable ignored) { } }
                    });
                }
                @Override public void onAttentionTone(boolean on) {
                    XposedBridge.log(TAG + ": [wx] attention tone " + (on ? "ON" : "off"));
                    wxStatus = wxStatus.replace(" \u2014 ATTENTION TONE", "") + (on ? " \u2014 ATTENTION TONE" : "");
                }
            });
            isWxMonitoringActive = true;
            currentChannelType = 1;
            XposedBridge.log(TAG + ": [wx] SAME monitoring started " + wxStatus);
            Toast.makeText(activity, "Weather alert monitoring " + wxStatus, Toast.LENGTH_SHORT).show();
        } catch (Throwable t) {
            XposedBridge.log(TAG + ": [wx] start error: " + t.getMessage());
        }
    }

    private void stopWxMonitoring(final Activity activity) {
        try {
            isWxMonitoringActive = false;
            wxDecoder = null;
            if (wxTuned) { restoreTxFreqBackup(); wxTuned = false; }
            wxStatus = "";
            XposedBridge.log(TAG + ": [wx] SAME monitoring stopped");
            Toast.makeText(activity, "Weather alert monitoring stopped", Toast.LENGTH_SHORT).show();
        } catch (Throwable t) {
            XposedBridge.log(TAG + ": [wx] stop error: " + t.getMessage());
        }
    }

    /** Append to the last-50 alert list in prefs dmrmod_wx/alerts (JSON). */
    // =====================================================================================
    // APRS messages / status received (backlog F2, 2026-10-17)
    // =====================================================================================

    private static volatile int aprsMsgNotifySeq = 0;

    /** True when the addressee is this station (CALL-SSID, or bare CALL when our SSID is 0). */
    private static boolean aprsAddressedToMe(android.content.Context ctx, String to) {
        try {
            APRSDatabase db = APRSDatabase.getInstance(ctx);
            String call = db.getCallsign();
            if (call == null || to == null) return false;
            call = call.trim().toUpperCase(java.util.Locale.US);
            String t = to.trim().toUpperCase(java.util.Locale.US);
            int ssid = db.getSSID();
            return t.equals(call + "-" + ssid) || (ssid == 0 && t.equals(call)) || t.equals(call + "-0") && ssid == 0;
        } catch (Throwable e) { return false; }
    }

    /** Called from the decode thread for every ':' message (incl. ack/rej). */
    static void aprsMessageReceived(final android.content.Context ctx, final APRSPacketDecoder.APRSPacket p) {
        try {
            final String from = p.sourceCallsign + (p.sourceSSID != 0 ? "-" + p.sourceSSID : "");
            final boolean mine = aprsAddressedToMe(ctx, p.messageTo);
            final boolean bulletin = p.messageTo != null && (p.messageTo.startsWith("BLN") || p.messageTo.startsWith("NWS"));
            String kind = p.isAck ? "ack" : p.isRej ? "rej" : "msg";
            aprsStoreLogEntry(ctx, kind, from, p.messageTo, p.messageText, p.messageId, mine);
            XposedBridge.log(TAG + ": [aprs] " + kind + " " + from + " -> " + p.messageTo + ": " + p.messageText
                    + (p.messageId != null ? " {" + p.messageId : "") + (mine ? "  (FOR US)" : ""));
            if (mine && !p.isAck && !p.isRej && p.messageId != null) {
                aprsMaybeAutoAck(ctx, from, p.messageId);
            }
            if ((mine || bulletin) && !p.isAck && !p.isRej) {
                aprsNotifyMessage(ctx, from, p.messageTo, p.messageText, mine);
                final String toastText = (mine ? "✉️ APRS message from " : "📢 APRS bulletin from ") + from + ": " + p.messageText;
                new android.os.Handler(android.os.Looper.getMainLooper()).post(new Runnable() {
                    @Override public void run() {
                        try { Toast.makeText(ctx, toastText, Toast.LENGTH_LONG).show(); } catch (Throwable ignored) {}
                    }
                });
            }
        } catch (Throwable t) {
            XposedBridge.log(TAG + ": [aprs] message handling error: " + t.getMessage());
        }
    }

    // =====================================================================================
    // =====================================================================================
    // APRS-IS (F4, 2026-10-17): RX-only iGate + internet position beacon + messages for us
    // =====================================================================================

    private static volatile AprsIsClient aprsIs = null;
    private static volatile String aprsIsStatus = "off";
    private static volatile Runnable aprsIsBeaconRunnable = null;
    private static volatile long aprsIsLastBeaconMs = 0;
    private static volatile int aprsIsMsgCount = 0;

    static boolean aprsIsEnabled(android.content.Context ctx) {
        try { return ctx.getSharedPreferences("dmrmod_aprs_global", android.content.Context.MODE_PRIVATE).getBoolean("is_enabled", false); }
        catch (Throwable t) { return false; }
    }

    /** Starts (or restarts) the APRS-IS client from the saved settings; no-op when disabled or no callsign. */
    static synchronized void aprsIsStart(final android.content.Context ctxIn) {
        try {
            final android.content.Context ctx = ctxIn.getApplicationContext() != null ? ctxIn.getApplicationContext() : ctxIn;
            aprsIsStop();
            android.content.SharedPreferences g = ctx.getSharedPreferences("dmrmod_aprs_global", android.content.Context.MODE_PRIVATE);
            if (!g.getBoolean("is_enabled", false)) return;
            APRSDatabase db = APRSDatabase.getInstance(ctx);
            String call = db.getCallsign() == null ? "" : db.getCallsign().trim().toUpperCase(java.util.Locale.US);
            if (call.isEmpty() || "N0CALL".equals(call)) { aprsIsStatus = "no callsign configured"; return; }
            final String login = call + (db.getSSID() != 0 ? "-" + db.getSSID() : "");
            String server = g.getString("is_server", "rotate.aprs2.net").trim();
            int port = g.getInt("is_port", 14580);
            String pass = g.getString("is_passcode", "-1").trim();
            if (pass.isEmpty()) pass = "-1";
            final int beaconMin = g.getInt("is_beacon_min", 10);
            AprsIsClient c = new AprsIsClient(server, port, login, pass, VERSION, null, new AprsIsClient.Listener() {
                @Override public void onStatus(String status, boolean connected) {
                    aprsIsStatus = status;
                    XposedBridge.log(TAG + ": [aprs-is] " + status);
                    if (connected && beaconMin > 0) aprsIsBeaconSoon(ctx, 5000);
                }
                @Override public void onServerLine(String line) { aprsIsHandleServerLine(ctx, line); }
            });
            aprsIs = c;
            c.start();
            if (beaconMin > 0) aprsIsScheduleBeacon(ctx, beaconMin);
            XposedBridge.log(TAG + ": [aprs-is] client started as " + login + " -> " + server + ":" + port
                    + (pass.equals("-1") ? " (receive-only, no passcode)" : "") + ", beacon every " + beaconMin + " min");
        } catch (Throwable t) {
            aprsIsStatus = "error: " + t.getMessage();
            XposedBridge.log(TAG + ": [aprs-is] start error: " + t.getMessage());
        }
    }

    static synchronized void aprsIsStop() {
        try {
            AprsIsClient c = aprsIs;
            aprsIs = null;
            if (c != null) c.stop();
            Runnable r = aprsIsBeaconRunnable;
            if (r != null) { new android.os.Handler(android.os.Looper.getMainLooper()).removeCallbacks(r); aprsIsBeaconRunnable = null; }
            aprsIsStatus = "off";
        } catch (Throwable t) { XposedBridge.log(TAG + ": [aprs-is] stop error: " + t.getMessage()); }
    }

    /** Called from the decode thread for every FCS-valid frame heard on RF (monitoring, passive, KISS). */
    static void aprsIgateFrame(byte[] frame) {
        try {
            AprsIsClient c = aprsIs;
            if (c == null || !c.isConnected()) return;
            String tnc2 = AprsIsClient.tnc2FromFrame(frame);
            if (tnc2 == null) return;
            if (!AprsIsClient.shouldGate(tnc2)) { XposedBridge.log(TAG + ": [aprs-is] not gated (path/type): " + tnc2); return; }
            boolean ok = c.gate(tnc2);
            XposedBridge.log(TAG + ": [aprs-is] " + (ok ? "gated: " : (c.isVerified() ? "gate failed: " : "not gated (unverified login): ")) + tnc2);
        } catch (Throwable t) { XposedBridge.log(TAG + ": [aprs-is] gate error: " + t.getMessage()); }
    }

    private static void aprsIsScheduleBeacon(final android.content.Context ctx, final int minutes) {
        final android.os.Handler h = new android.os.Handler(android.os.Looper.getMainLooper());
        Runnable old = aprsIsBeaconRunnable;
        if (old != null) h.removeCallbacks(old);
        Runnable r = new Runnable() {
            @Override public void run() {
                if (aprsIs == null) return;
                aprsIsSendBeacon(ctx);
                h.postDelayed(this, minutes * 60000L);
            }
        };
        aprsIsBeaconRunnable = r;
        h.postDelayed(r, minutes * 60000L);
    }

    private static void aprsIsBeaconSoon(final android.content.Context ctx, long delayMs) {
        new android.os.Handler(android.os.Looper.getMainLooper()).postDelayed(new Runnable() {
            @Override public void run() { if (System.currentTimeMillis() - aprsIsLastBeaconMs > 60000) aprsIsSendBeacon(ctx); }
        }, delayMs);
    }

    /** Position beacon straight to APRS-IS (TCPIP*): the phone's last known location, APRS symbol from settings. */
    static void aprsIsSendBeacon(final android.content.Context ctx) {
        new Thread(new Runnable() { @Override public void run() {
            try {
                AprsIsClient c = aprsIs;
                if (c == null || !c.isConnected() || !c.isVerified()) return;
                android.location.Location loc = SatellitePassPredictor.getLastLocation(ctx);
                if (loc == null) { XposedBridge.log(TAG + ": [aprs-is] beacon skipped: no location"); return; }
                APRSDatabase db = APRSDatabase.getInstance(ctx);
                android.content.SharedPreferences g = ctx.getSharedPreferences("dmrmod_aprs_global", android.content.Context.MODE_PRIVATE);
                String comment = g.getString("is_beacon_comment", "DMRModHooks");
                String info = buildAprsPositionInfo(loc.getLatitude(), loc.getLongitude(), db.getDefaultSymbolTable(), db.getDefaultSymbolCode(), comment);
                String line = c.getLogin() + ">APDR16,TCPIP*:" + info;
                boolean ok = c.send(line);
                if (ok) aprsIsLastBeaconMs = System.currentTimeMillis();
                XposedBridge.log(TAG + ": [aprs-is] beacon " + (ok ? "sent" : "FAILED") + ": " + line);
            } catch (Throwable t) { XposedBridge.log(TAG + ": [aprs-is] beacon error: " + t.getMessage()); }
        } }, "dmrmod-aprs-is-beacon").start();
    }

    /** Server lines: messages addressed to our login (delivered without a filter) are stored, notified and acked over IS. */
    private static void aprsIsHandleServerLine(final android.content.Context ctx, String line) {
        try {
            APRSPacketDecoder.APRSPacket p = APRSPacketDecoder.decodeTnc2(line);
            if (!p.isValid || !p.isMessage()) return;
            if (!aprsAddressedToMe(ctx, p.messageTo)) return;
            aprsIsMsgCount++;
            final String from = p.sourceCallsign + (p.sourceSSID != 0 ? "-" + p.sourceSSID : "");
            if (p.isAck || p.isRej) {
                aprsStoreLogEntry(ctx, p.isAck ? "ack" : "rej", from + " (IS)", p.messageTo, p.messageText, p.messageId, true);
                return;
            }
            aprsStoreLogEntry(ctx, "msg", from + " (IS)", p.messageTo, p.messageText, p.messageId, true);
            aprsNotifyMessage(ctx, from + " via APRS-IS", p.messageTo, p.messageText, true);
            final String toastText = "✉️ APRS-IS message from " + from + ": " + p.messageText;
            new android.os.Handler(android.os.Looper.getMainLooper()).post(new Runnable() {
                @Override public void run() { try { Toast.makeText(ctx, toastText, Toast.LENGTH_LONG).show(); } catch (Throwable ignored) {} }
            });
            AprsIsClient c = aprsIs;
            if (p.messageId != null && c != null && c.isVerified()) {
                String a = from.length() > 9 ? from.substring(0, 9) : from;
                StringBuilder sb = new StringBuilder(":").append(a);
                for (int i = a.length(); i < 9; i++) sb.append(' ');
                String ack = c.getLogin() + ">APDR16,TCPIP*:" + sb.append(":ack").append(p.messageId);
                c.send(ack);
                XposedBridge.log(TAG + ": [aprs-is] acked over IS: " + ack);
            }
        } catch (Throwable t) { XposedBridge.log(TAG + ": [aprs-is] server line error: " + t.getMessage()); }
    }

    // Fill-in digipeater (WIDE1-1), 2026-10-17 — APRS monitoring only, setting default OFF
    // =====================================================================================

    private static volatile int aprsDigiEnabled = -1;   // -1 not loaded, 0 off, 1 on
    private static final java.util.HashMap<String, Long> aprsDigiSeen = new java.util.HashMap<>();

    private static boolean aprsDigiWanted(android.content.Context ctx) {
        int e = aprsDigiEnabled;
        if (e < 0) {
            try {
                e = ctx.getSharedPreferences("dmrmod_aprs_global", android.content.Context.MODE_PRIVATE).getBoolean("digipeat", false) ? 1 : 0;
                aprsDigiEnabled = e;
            } catch (Throwable t) { return false; }
        }
        return e == 1;
    }

    /**
     * Called for every FCS-valid AX.25 frame heard (parsed or not). Repeats it once when the first
     * unused digipeater hop is WIDE1-1 (or our own callsign-SSID), replacing that hop with our
     * callsign marked used — the "new paradigm" fill-in behaviour. Never repeats our own frames,
     * frames already carrying our callsign, frames with no digipeater field, or a frame seen in the
     * last 30 s (same source + payload). Transmits one copy after a 0.5-1.5 s random hold-off.
     */
    static void aprsMaybeDigipeat(final android.content.Context ctx, final byte[] frame) {
        try {
            if (!isAPRSMonitoringActive || kissActive) return;
            if (!aprsDigiWanted(ctx)) return;
            if (frame == null || frame.length < 16) return;
            APRSDatabase db = APRSDatabase.getInstance(ctx);
            final String myCall = db.getCallsign() == null ? "" : db.getCallsign().trim().toUpperCase(java.util.Locale.US);
            final int mySsid = db.getSSID();
            if (myCall.isEmpty() || "N0CALL".equals(myCall)) return;

            // walk the address field
            int off = 0;
            String dst = ax25Addr(frame, 0), src = ax25Addr(frame, 7);
            if (src.equals(myCall + (mySsid != 0 ? "-" + mySsid : ""))) return;        // our own
            boolean last = (frame[13] & 0x01) != 0;
            off = 14;
            int hopOff = -1;
            while (!last && off + 7 <= frame.length) {
                String digi = ax25Addr(frame, off);
                boolean used = (frame[off + 6] & 0x80) != 0;
                if (digi.equals(myCall) || digi.equals(myCall + "-" + mySsid)) { if (used) return; }   // already repeated by us
                if (!used && hopOff < 0) {
                    if (digi.equals("WIDE1-1") || digi.equals(myCall + "-" + mySsid) || (mySsid == 0 && digi.equals(myCall))) hopOff = off;
                    else return;                                                        // first unused hop is not ours
                }
                last = (frame[off + 6] & 0x01) != 0;
                off += 7;
            }
            if (hopOff < 0) return;
            if (off + 2 > frame.length) return;
            int infoStart = off + 2;

            // de-dupe on source + payload for 30 s
            String key = src + ":" + new String(frame, infoStart, frame.length - infoStart, java.nio.charset.StandardCharsets.ISO_8859_1);
            long now = System.currentTimeMillis();
            synchronized (aprsDigiSeen) {
                Long t = aprsDigiSeen.get(key);
                if (t != null && now - t < 30000) return;
                aprsDigiSeen.put(key, now);
                if (aprsDigiSeen.size() > 500) aprsDigiSeen.clear();
            }

            // build the repeated frame: hop := MYCALL-SSID with H bit set, everything else untouched
            final byte[] out = frame.clone();
            String call = (myCall + "      ").substring(0, 6);
            for (int i = 0; i < 6; i++) out[hopOff + i] = (byte) ((call.charAt(i) << 1) & 0xFF);
            out[hopOff + 6] = (byte) ((frame[hopOff + 6] & 0x01) | 0x60 | ((mySsid & 0x0F) << 1) | 0x80);

            final String label = "digi " + src + ">" + dst;
            int holdMs = 500 + new java.util.Random().nextInt(1000);
            XposedBridge.log(TAG + ": [digi] " + src + ">" + dst + " via WIDE1-1 -> repeating as " + myCall + "-" + mySsid + "* in " + holdMs + " ms");
            new android.os.Handler(android.os.Looper.getMainLooper()).postDelayed(new Runnable() {
                @Override public void run() {
                    new Thread(new Runnable() { @Override public void run() {
                        try {
                            if (!isAPRSMonitoringActive || kissActive) return;
                            int ms = transmitRawAx25(ctx, out, label, false, 1);
                            aprsStoreLogEntry(ctx, "digi", src, dst, "repeated via " + myCall + "-" + mySsid, null, false);
                            XposedBridge.log(TAG + ": [digi] " + (ms < 0 ? "FAILED" : "repeated (" + ms + " ms)") + ": " + label);
                        } catch (Throwable t) { XposedBridge.log(TAG + ": [digi] error: " + t.getMessage()); }
                    } }, "dmrmod-aprs-digi").start();
                }
            }, holdMs);
        } catch (Throwable t) {
            XposedBridge.log(TAG + ": [digi] error: " + t.getMessage());
        }
    }

    /** "CALL-SSID" (no "-0") from an AX.25 address field. */
    private static String ax25Addr(byte[] f, int off) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 6; i++) { char c = (char) ((f[off + i] & 0xFF) >> 1); if (c != ' ') sb.append(c); }
        int ssid = (f[off + 6] >> 1) & 0x0F;
        if (ssid != 0) sb.append('-').append(ssid);
        return sb.toString();
    }

    private static final java.util.HashMap<String, Long> aprsAckSent = new java.util.HashMap<>();

    /**
     * APRS protocol: a message with a {id must be acknowledged ("ackID" back to the sender) or the
     * sender keeps retrying. Done only while APRS monitoring is on (the radio is parked on the APRS
     * frequency; KISS mode leaves acks to the client app), gated by the "auto-ack" setting
     * (prefs dmrmod_aprs_global/auto_ack, default on), at most once per sender+id per 10 s, after a
     * 1.5-3 s random hold-off so two stations acking at once do not collide.
     */
    private static void aprsMaybeAutoAck(final android.content.Context ctx, final String from, final String id) {
        try {
            if (!isAPRSMonitoringActive || kissActive) return;
            android.content.SharedPreferences g = ctx.getSharedPreferences("dmrmod_aprs_global", android.content.Context.MODE_PRIVATE);
            if (!g.getBoolean("auto_ack", true)) return;
            final String key = from + "{" + id;
            long now = System.currentTimeMillis();
            synchronized (aprsAckSent) {
                Long last = aprsAckSent.get(key);
                if (last != null && now - last < 10000) { XposedBridge.log(TAG + ": [aprs] ack " + key + " already sent, skipping"); return; }
                aprsAckSent.put(key, now);
                if (aprsAckSent.size() > 200) aprsAckSent.clear();
            }
            APRSDatabase db = APRSDatabase.getInstance(ctx);
            final String myCall = db.getCallsign();
            final int mySsid = db.getSSID();
            if (myCall == null || myCall.trim().isEmpty() || "N0CALL".equalsIgnoreCase(myCall.trim())) {
                XposedBridge.log(TAG + ": [aprs] auto-ack skipped: no callsign configured");
                return;
            }
            String a = from.toUpperCase(java.util.Locale.US);
            if (a.length() > 9) a = a.substring(0, 9);
            StringBuilder sb = new StringBuilder(":").append(a);
            for (int i = a.length(); i < 9; i++) sb.append(' ');
            final String info = sb.append(":ack").append(id).toString();
            final String label = "ack " + id + " → " + from;
            int holdMs = 1500 + new java.util.Random().nextInt(1500);
            XposedBridge.log(TAG + ": [aprs] auto-ack scheduled in " + holdMs + " ms: " + info);
            new android.os.Handler(android.os.Looper.getMainLooper()).postDelayed(new Runnable() {
                @Override public void run() {
                    new Thread(new Runnable() { @Override public void run() {
                        try {
                            if (!isAPRSMonitoringActive || kissActive) return;
                            int ms = transmitAprsPacket(ctx, myCall.trim(), mySsid, new String[]{ "WIDE1-1" }, info, label,
                                    APRS_TX_LEAD_MS, 1, 0);
                            aprsStoreLogEntry(ctx, "ack-tx", myCall.trim() + "-" + mySsid, from, "ack" + id, id, false);
                            XposedBridge.log(TAG + ": [aprs] auto-ack " + (ms < 0 ? "FAILED" : "sent (" + ms + " ms)") + ": " + info);
                        } catch (Throwable t) { XposedBridge.log(TAG + ": [aprs] auto-ack error: " + t.getMessage()); }
                    } }, "dmrmod-aprs-ack").start();
                }
            }, holdMs);
        } catch (Throwable t) {
            XposedBridge.log(TAG + ": [aprs] auto-ack error: " + t.getMessage());
        }
    }

    /** Called from the decode thread for every '>' status report. */
    static void aprsStatusReceived(android.content.Context ctx, APRSPacketDecoder.APRSPacket p) {
        try {
            String from = p.sourceCallsign + (p.sourceSSID != 0 ? "-" + p.sourceSSID : "");
            aprsStoreLogEntry(ctx, "status", from, null, p.status, null, false);
        } catch (Throwable t) {
            XposedBridge.log(TAG + ": [aprs] status handling error: " + t.getMessage());
        }
    }

    /** Message/status log: prefs dmrmod_aprs/messages, newest last, capped at 100 entries. */
    private static void aprsStoreLogEntry(android.content.Context ctx, String kind, String from, String to,
                                          String text, String id, boolean mine) {
        try {
            android.content.SharedPreferences prefs = ctx.getSharedPreferences("dmrmod_aprs", android.content.Context.MODE_PRIVATE);
            org.json.JSONArray arr = new org.json.JSONArray(prefs.getString("messages", "[]"));
            org.json.JSONObject o = new org.json.JSONObject();
            o.put("t", System.currentTimeMillis()); o.put("kind", kind); o.put("from", from);
            if (to != null) o.put("to", to);
            o.put("text", text == null ? "" : text);
            if (id != null) o.put("id", id);
            o.put("mine", mine);
            arr.put(o);
            while (arr.length() > 100) arr.remove(0);
            prefs.edit().putString("messages", arr.toString()).apply();
        } catch (Throwable t) {
            XposedBridge.log(TAG + ": [aprs] log store error: " + t.getMessage());
        }
    }

    private static void aprsNotifyMessage(android.content.Context ctx, String from, String to, String text, boolean mine) {
        try {
            android.app.NotificationManager nm = (android.app.NotificationManager) ctx.getSystemService(android.content.Context.NOTIFICATION_SERVICE);
            if (nm == null) return;
            android.app.Notification.Builder b;
            if (android.os.Build.VERSION.SDK_INT >= 26) {
                android.app.NotificationChannel ch = new android.app.NotificationChannel("dmrmod_aprs_msg", "APRS messages", android.app.NotificationManager.IMPORTANCE_HIGH);
                nm.createNotificationChannel(ch);
                b = new android.app.Notification.Builder(ctx, "dmrmod_aprs_msg");
            } else {
                b = new android.app.Notification.Builder(ctx);
            }
            b.setSmallIcon(android.R.drawable.stat_notify_chat)
             .setContentTitle((mine ? "APRS message from " : "APRS bulletin from ") + from + (mine ? "" : " to " + to))
             .setContentText(text)
             .setStyle(new android.app.Notification.BigTextStyle().bigText(text))
             .setAutoCancel(true)
             .setDefaults(android.app.Notification.DEFAULT_ALL);
            nm.notify(7300 + (aprsMsgNotifySeq++ % 50), b.build());
        } catch (Throwable t) {
            XposedBridge.log(TAG + ": [aprs] notify error: " + t.getMessage());
        }
    }

    /** "Messages" section at the top of the Received APRS dialog: last 20 entries, newest first. */
    private static void aprsAddMessagesSection(Activity activity, LinearLayout parent) {
        try {
            android.content.SharedPreferences prefs = activity.getSharedPreferences("dmrmod_aprs", android.content.Context.MODE_PRIVATE);
            org.json.JSONArray arr = new org.json.JSONArray(prefs.getString("messages", "[]"));
            TextView head = new TextView(activity);
            head.setText("✉️ Messages & status (" + arr.length() + ")" + (arr.length() > 0 ? "  — tap one to reply" : ""));
            head.setTextSize(16);
            head.setTypeface(null, android.graphics.Typeface.BOLD);
            head.setTextColor(0xFFFFCC66);
            head.setPadding(0, 0, 0, 8);
            parent.addView(head);
            if (arr.length() == 0) {
                TextView none = new TextView(activity);
                none.setText("No APRS messages, acks or status reports decoded yet. Messages addressed to your callsign raise a notification.");
                none.setTextSize(13); none.setTextColor(0xFF999999); none.setPadding(0, 0, 0, 20);
                parent.addView(none);
                return;
            }
            java.text.SimpleDateFormat fmt = new java.text.SimpleDateFormat("MM-dd HH:mm", java.util.Locale.US);
            int shown = 0;
            for (int i = arr.length() - 1; i >= 0 && shown < 20; i--, shown++) {
                org.json.JSONObject o = arr.getJSONObject(i);
                String kind = o.optString("kind", "msg");
                boolean mine = o.optBoolean("mine", false);
                String line;
                String from = o.optString("from", "?");
                String when = fmt.format(new java.util.Date(o.optLong("t", 0)));
                if ("status".equals(kind)) {
                    line = when + "  " + from + " status: " + o.optString("text", "");
                } else if ("digi".equals(kind)) {
                    line = when + "  \uD83D\uDD01 digipeated " + from + " > " + o.optString("to", "");
                } else if ("ack-tx".equals(kind)) {
                    line = when + "  ✓ acked " + o.optString("id", "") + " → " + o.optString("to", "") + " (sent by us)";
                } else if ("ack".equals(kind) || "rej".equals(kind)) {
                    line = when + "  " + from + " " + kind + " " + o.optString("id", "") + " → " + o.optString("to", "");
                } else {
                    line = when + "  " + from + " → " + o.optString("to", "") + ": " + o.optString("text", "")
                         + (o.has("id") ? "  {" + o.optString("id") : "");
                }
                TextView t = new TextView(activity);
                t.setText((mine ? "⭐ " : "") + line);
                t.setTextSize(13);
                // the dialog background is light: dark text, bold + blue for messages addressed to us
                t.setTextColor(mine ? 0xFF1E5AA8 : "status".equals(kind) ? 0xFF888888 : 0xFF444444);
                if (mine) t.setTypeface(null, android.graphics.Typeface.BOLD);
                t.setPadding(0, 2, 0, 2);
                // tap a message/ack from another station to reply to it (compose pre-filled)
                if (!"status".equals(kind) && !o.optString("kind", "").equals("ack-tx")) {
                    final String replyTo = from.replace(" (IS)", "").trim();
                    t.setOnClickListener(new View.OnClickListener() {
                        @Override public void onClick(View v) {
                            MainHook mi = moduleInstance;
                            if (mi != null) mi.showAprsSendMessageDialog(activity, replyTo);
                        }
                    });
                }
                parent.addView(t);
            }
            View div = new View(activity);
            div.setBackgroundColor(0x33FFFFFF);
            LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, 1);
            lp.topMargin = 12; lp.bottomMargin = 16;
            div.setLayoutParams(lp);
            parent.addView(div);
        } catch (Throwable t) {
            XposedBridge.log(TAG + ": [aprs] messages section error: " + t.getMessage());
        }
    }

    private static void wxStoreAlert(android.content.Context ctx, SAMEDecoder.Message m) {
        try {
            android.content.SharedPreferences prefs = ctx.getSharedPreferences("dmrmod_wx", android.content.Context.MODE_PRIVATE);
            org.json.JSONArray arr = new org.json.JSONArray(prefs.getString("alerts", "[]"));
            org.json.JSONObject o = new org.json.JSONObject();
            o.put("t", m.receivedMs); o.put("raw", m.raw); o.put("summary", m.summary());
            o.put("event", m.event); o.put("eom", m.eom);
            arr.put(o);
            while (arr.length() > 50) arr.remove(0);
            prefs.edit().putString("alerts", arr.toString()).apply();
        } catch (Throwable t) {
            XposedBridge.log(TAG + ": [wx] store error: " + t.getMessage());
        }
    }

    private static void wxNotify(android.content.Context ctx, SAMEDecoder.Message m) {
        try {
            android.app.NotificationManager nm = (android.app.NotificationManager) ctx.getSystemService(android.content.Context.NOTIFICATION_SERVICE);
            if (nm == null) return;
            android.app.Notification.Builder b;
            if (android.os.Build.VERSION.SDK_INT >= 26) {
                android.app.NotificationChannel ch = new android.app.NotificationChannel("dmrmod_wx", "Weather alerts (SAME)", android.app.NotificationManager.IMPORTANCE_HIGH);
                nm.createNotificationChannel(ch);
                b = new android.app.Notification.Builder(ctx, "dmrmod_wx");
            } else {
                b = new android.app.Notification.Builder(ctx);
            }
            b.setSmallIcon(android.R.drawable.ic_dialog_alert)
             .setContentTitle("\u26C8\uFE0F " + (m.eventName.isEmpty() ? m.event : m.eventName))
             .setContentText(m.summary())
             .setStyle(new android.app.Notification.BigTextStyle().bigText(m.summary() + "\n" + m.raw))
             .setAutoCancel(true);
            nm.notify(wxNotifyId++, b.build());
        } catch (Throwable t) {
            XposedBridge.log(TAG + ": [wx] notify error: " + t.getMessage());
        }
    }

    // -----------------------------------------------------------------------
    // NOAA Doppler tracking
    // -----------------------------------------------------------------------

    /**
     * Every 5 s predict the Doppler shift of the satellite on the monitored frequency (needs a last
     * known location); when the shift crosses into another 2.5 kHz step, re-tune the radio
     * (hardware-only) to nominal + step. Outside a pass (satellite below the horizon) the radio sits
     * on the nominal frequency. The decoder re-syncs after the ~1.2 s audio gap a retune causes.
     */
    private void startNoaaDopplerTracking(final Activity activity) {
        stopNoaaDopplerTracking();
        if (!noaaDopplerEnabled) { noaaDopplerStatus = ""; return; }
        final android.location.Location loc = SatellitePassPredictor.getLastLocation(activity);
        if (loc == null) {
            noaaDopplerStatus = "Doppler: no location fix \u2014 tracking off";
            XposedBridge.log(TAG + ": [noaa-doppler] no location, tracking disabled");
            return;
        }
        final String satName = SatellitePassPredictor.satelliteForFrequency(noaaBaseFreqHz);
        if (satName == null) {
            noaaDopplerStatus = "Doppler: no NOAA satellite on " + (noaaBaseFreqHz / 1e6) + " MHz";
            return;
        }
        noaaDopplerStatus = "Doppler: " + satName + " \u2014 waiting for pass";
        // refresh the orbital elements in the background (fallback TLEs age; the tracker keeps
        // running on whatever is loaded and picks up the fresh set on its next tick)
        new Thread(new Runnable() { @Override public void run() {
            try { SatellitePassPredictor.fetchFreshTles(); } catch (Throwable ignored) { }
        } }, "dmrmod-tle-refresh").start();
        noaaDopplerHandler = new android.os.Handler(android.os.Looper.getMainLooper());
        noaaDopplerRunnable = new Runnable() {
            @Override public void run() {
                if (!isNOAAMonitoringActive) return;
                try {
                    double shift = SatellitePassPredictor.dopplerHz(noaaBaseFreqHz, loc.getLatitude(),
                            loc.getLongitude(), loc.getAltitude(), System.currentTimeMillis());
                    int step = (int) Math.round(shift / NOAA_DOPPLER_STEP_HZ) * NOAA_DOPPLER_STEP_HZ;
                    if (shift == 0) {
                        noaaDopplerStatus = "Doppler: " + satName + " below horizon \u2014 on nominal";
                    } else {
                        noaaDopplerStatus = String.format(java.util.Locale.US,
                            "Doppler: %s %+.1f kHz \u2192 tuned %+.1f kHz", satName, shift / 1000.0, step / 1000.0);
                    }
                    if (step != noaaAppliedOffsetHz) {
                        noaaAppliedOffsetHz = step;
                        XposedBridge.log(TAG + ": [noaa-doppler] " + satName + " predicted "
                            + String.format(java.util.Locale.US, "%+.0f", shift) + " Hz -> retune "
                            + ((noaaBaseFreqHz + step) / 1e6) + " MHz");
                        tuneCurrentChannelAnalog(noaaBaseFreqHz + step, 1);
                    }
                } catch (Throwable t) {
                    XposedBridge.log(TAG + ": [noaa-doppler] " + t.getMessage());
                }
                if (noaaDopplerHandler != null) noaaDopplerHandler.postDelayed(this, 5000);
            }
        };
        noaaDopplerHandler.postDelayed(noaaDopplerRunnable, 2000);
    }

    private static void stopNoaaDopplerTracking() {
        if (noaaDopplerHandler != null && noaaDopplerRunnable != null) {
            noaaDopplerHandler.removeCallbacks(noaaDopplerRunnable);
        }
        noaaDopplerHandler = null;
        noaaDopplerRunnable = null;
        noaaDopplerStatus = "";
        noaaAppliedOffsetHz = 0;
    }

    // -----------------------------------------------------------------------
    // NOAA channel backup / restore  (same pattern as SSTV)
    // -----------------------------------------------------------------------

    private void saveNOAAChannelBackup(Object channel) {
        try {
            noaaChannelBackup = new java.util.HashMap<>();
            noaaChannelBackup.put("number",      XposedHelpers.getIntField(channel, "number"));
            noaaChannelBackup.put("type",        XposedHelpers.getIntField(channel, "type"));
            noaaChannelBackup.put("name",        XposedHelpers.getObjectField(channel, "name"));
            noaaChannelBackup.put("rxFreq",      XposedHelpers.getIntField(channel, "rxFreq"));
            noaaChannelBackup.put("txFreq",      XposedHelpers.getIntField(channel, "txFreq"));
            noaaChannelBackup.put("sq",          XposedHelpers.getIntField(channel, "sq"));
            noaaChannelBackup.put("band",        XposedHelpers.getIntField(channel, "band"));
            noaaChannelBackup.put("power",       XposedHelpers.getIntField(channel, "power"));
            try {
                noaaChannelBackup.put("channelMode", XposedHelpers.getIntField(channel, "channelMode"));
            } catch (Throwable t) { noaaChannelBackup.put("channelMode", 0); }
            try {
                noaaChannelBackup.put("rxType",    XposedHelpers.getIntField(channel, "rxType"));
                noaaChannelBackup.put("rxSubCode", XposedHelpers.getIntField(channel, "rxSubCode"));
                noaaChannelBackup.put("txType",    XposedHelpers.getIntField(channel, "txType"));
                noaaChannelBackup.put("txSubCode", XposedHelpers.getIntField(channel, "txSubCode"));
            } catch (Throwable t) {
                noaaChannelBackup.put("rxType", 0); noaaChannelBackup.put("rxSubCode", 0);
                noaaChannelBackup.put("txType", 0); noaaChannelBackup.put("txSubCode", 0);
            }
            ModeBackupStore.save("noaa", noaaChannelBackup);   // S3
            XposedBridge.log(TAG + ": NOAA channel backup saved: " + noaaChannelBackup.get("name"));
        } catch (Exception e) {
            XposedBridge.log(TAG + ": Error saving NOAA channel backup: " + e.getMessage());
        }
    }

    private void restoreNOAAChannelBackup(Context context) {
        try {
            if (noaaChannelBackup == null) {
                java.util.HashMap<String, Object> loaded = ModeBackupStore.load("noaa");   // S3
                if (loaded == null) { XposedBridge.log(TAG + ": No NOAA backup file"); return; }
                noaaChannelBackup = loaded;
            }
            Class<?> dmrClass = XposedHelpers.findClass(
                "com.pri.prizeinterphone.manager.DmrManager", appClassLoader);
            Object mgr = XposedHelpers.callStaticMethod(dmrClass, "getInstance");
            Object ch  = XposedHelpers.callMethod(mgr, "getCurrentChannel");
            if (ch == null) { XposedBridge.log(TAG + ": Cannot get channel for NOAA restore"); return; }
            Object n = noaaChannelBackup.get("number"); if (n != null) XposedHelpers.setIntField(ch, "number", (Integer) n);
            Object tp = noaaChannelBackup.get("type");  if (tp != null) XposedHelpers.setIntField(ch, "type",  (Integer) tp);
            Object nm = noaaChannelBackup.get("name");  XposedHelpers.setObjectField(ch, "name", nm != null ? (String) nm : "Channel");
            Object rf = noaaChannelBackup.get("rxFreq"); if (rf != null) XposedHelpers.setIntField(ch, "rxFreq", (Integer) rf);
            Object tf = noaaChannelBackup.get("txFreq"); if (tf != null) XposedHelpers.setIntField(ch, "txFreq", (Integer) tf);
            Object sq = noaaChannelBackup.get("sq");    if (sq != null) XposedHelpers.setIntField(ch, "sq",    (Integer) sq);
            Object bd = noaaChannelBackup.get("band");  if (bd != null) XposedHelpers.setIntField(ch, "band",  (Integer) bd);
            Object pw = noaaChannelBackup.get("power"); if (pw != null) XposedHelpers.setIntField(ch, "power", (Integer) pw);
            Object cm = noaaChannelBackup.get("channelMode");
            try { if (cm != null) XposedHelpers.setIntField(ch, "channelMode", (Integer) cm); } catch (Throwable ignored) {}
            Object rt = noaaChannelBackup.get("rxType");    if (rt != null) XposedHelpers.setIntField(ch, "rxType",    (Integer) rt);
            Object rs = noaaChannelBackup.get("rxSubCode"); if (rs != null) XposedHelpers.setIntField(ch, "rxSubCode", (Integer) rs);
            Object tt = noaaChannelBackup.get("txType");    if (tt != null) XposedHelpers.setIntField(ch, "txType",    (Integer) tt);
            Object ts = noaaChannelBackup.get("txSubCode"); if (ts != null) XposedHelpers.setIntField(ch, "txSubCode", (Integer) ts);
            try {
                // hardware-only (no updateChannel): the hijack never wrote the DB
                XposedHelpers.callMethod(mgr, "syncChannelInfoWithData", ch);
            } catch (Throwable t) {
                XposedBridge.log(TAG + ": NOAA restore sync warning: " + t.getMessage());
            }
            XposedBridge.log(TAG + ": NOAA channel restored: " + noaaChannelBackup.get("name"));
            noaaChannelBackup = null;
            ModeBackupStore.delete("noaa");
        } catch (Exception e) {
            XposedBridge.log(TAG + ": Error restoring NOAA channel: " + e.getMessage());
        }
    }

    /** Called on app startup: detect and repair orphaned NOAA channel. */
    private void checkAndRestoreNOAAChannelOnStartup(final Context context) {
        boolean deleteBackup = false;
        try {
            if (!ModeBackupStore.exists("noaa")) return;   // S3
            deleteBackup = true;

            Class<?> dmrClass = XposedHelpers.findClass(
                "com.pri.prizeinterphone.manager.DmrManager", appClassLoader);
            Object mgr = XposedHelpers.callStaticMethod(dmrClass, "getInstance");
            if (mgr == null) return;
            Object ch = XposedHelpers.callMethod(mgr, "getCurrentChannel");
            if (ch == null) return;

            String name = (String) XposedHelpers.getObjectField(ch, "name");
            XposedBridge.log(TAG + ": NOAA startup check — channel: " + name);

            if (name != null && name.startsWith("NOAA (")) {
                XposedBridge.log(TAG + ": Restoring orphaned NOAA channel...");
                java.util.HashMap<String, Object> backup = ModeBackupStore.load("noaa");   // S3
                if (backup == null) {
                    XposedBridge.log(TAG + ": NOAA backup unreadable - nothing to restore");
                    return;
                }
                noaaChannelBackup = backup;
                restoreNOAAChannelBackup(context);
                deleteBackup = false;  // restoreNOAAChannelBackup already deletes it
                if (context instanceof Activity) {
                    ((Activity) context).runOnUiThread(new Runnable() {
                        @Override
                        public void run() {
                            try {
                                if (context instanceof Activity) {
                                    Activity a = (Activity) context;
                                    if (a.isFinishing() || a.isDestroyed()) return;
                                }
                                new AlertDialog.Builder(context)
                                    .setTitle("\u26a0\ufe0f NOAA Channel Restored")
                                    .setMessage("NOAA APT monitoring was interrupted while the app was closed.\n\n" +
                                        "Your original channel has been restored automatically.\n\n" +
                                        "To prevent this:\n" +
                                        "\u2022 Always stop NOAA monitoring before closing the app\n\n" +
                                        "Restart recommended for proper operation.")
                                    .setPositiveButton("Restart App", new DialogInterface.OnClickListener() {
                                        @Override
                                        public void onClick(DialogInterface dialog, int which) {
                                            try {
                                                Context appContext = context.getApplicationContext();
                                                String packageName = appContext.getPackageName();
                                                android.content.Intent intent = appContext.getPackageManager()
                                                    .getLaunchIntentForPackage(packageName);
                                                if (intent != null) {
                                                    intent.addFlags(android.content.Intent.FLAG_ACTIVITY_CLEAR_TOP);
                                                    intent.addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK);
                                                    android.app.PendingIntent pendingIntent = android.app.PendingIntent.getActivity(
                                                        appContext, 0, intent,
                                                        android.app.PendingIntent.FLAG_ONE_SHOT | android.app.PendingIntent.FLAG_IMMUTABLE);
                                                    android.app.AlarmManager alarmManager = (android.app.AlarmManager)
                                                        appContext.getSystemService(Context.ALARM_SERVICE);
                                                    alarmManager.set(android.app.AlarmManager.RTC,
                                                        System.currentTimeMillis() + 100, pendingIntent);
                                                    XposedBridge.log(TAG + ": Restarting app after NOAA recovery...");
                                                    System.exit(0);
                                                }
                                            } catch (Exception restartEx) {
                                                XposedBridge.log(TAG + ": Error restarting app: " + restartEx.getMessage());
                                                Toast.makeText(context, "Error restarting app", Toast.LENGTH_SHORT).show();
                                            }
                                        }
                                    })
                                    .setCancelable(false)
                                    .show();
                            } catch (Exception ex) {
                                XposedBridge.log(TAG + ": Error showing NOAA restore dialog: " + ex.getMessage());
                            }
                        }
                    });
                }
                XposedBridge.log(TAG + ": NOAA crash recovery completed");
            }
        } catch (Exception e) {
            XposedBridge.log(TAG + ": NOAA startup check error: " + e.getMessage());
        } finally {
            if (deleteBackup) {
                try { ModeBackupStore.delete("noaa"); } catch (Exception ignored) {}
            }
        }
    }

