    /** 8 kHz mono DTMF audio: 300 ms silence, then each key toneMs on / gapMs off, 200 ms tail. */
    static short[] dtmfPcm(String seq, int toneMs, int gapMs) {
        final int SR = 8000;
        final double[] low = { 697, 770, 852, 941 }, high = { 1209, 1336, 1477, 1633 };
        final String[] rows = { "123A", "456B", "789C", "*0#D" };
        int toneN = SR * toneMs / 1000, gapN = SR * gapMs / 1000;
        int n = SR * 300 / 1000 + seq.length() * (toneN + gapN) + SR * 200 / 1000;
        short[] out = new short[n];
        int pos = SR * 300 / 1000;
        for (char c : seq.toCharArray()) {
            int r = -1, col = -1;
            for (int i = 0; i < 4; i++) { int j = rows[i].indexOf(c); if (j >= 0) { r = i; col = j; } }
            if (r >= 0) {
                for (int i = 0; i < toneN; i++) {
                    double v = 0.38 * 32767 * (Math.sin(2 * Math.PI * low[r] * i / SR) + Math.sin(2 * Math.PI * high[col] * i / SR));
                    // 5 ms raised-cosine edges against key clicks
                    int edge = SR * 5 / 1000;
                    if (i < edge) v *= 0.5 * (1 - Math.cos(Math.PI * i / edge));
                    else if (i >= toneN - edge) v *= 0.5 * (1 - Math.cos(Math.PI * (toneN - 1 - i) / edge));
                    out[pos + i] = (short) Math.max(-32768, Math.min(32767, v));
                }
            }
            pos += toneN + gapN;
        }
        return out;
    }

    private static String dtmfHistoryText(android.content.SharedPreferences prefs) {
        try {
            org.json.JSONArray arr = new org.json.JSONArray(prefs.getString("log", "[]"));
            if (arr.length() == 0) return "(none yet)";
            java.text.SimpleDateFormat fmt = new java.text.SimpleDateFormat("MM-dd HH:mm:ss", java.util.Locale.US);
            StringBuilder sb = new StringBuilder();
            for (int i = arr.length() - 1; i >= 0; i--) {
                org.json.JSONObject o = arr.getJSONObject(i);
                sb.append(fmt.format(new java.util.Date(o.optLong("t", 0)))).append("  ")
                  .append(o.optString("d", "")).append("   ch ").append(o.optInt("ch", -1)).append(" ").append(o.optString("name", "")).append('\n');
            }
            return sb.toString().trim();
        } catch (Throwable t) { return "(error: " + t.getMessage() + ")"; }
    }

    /** True when the current audio should be fed to the AFSK decoder although no APRS/KISS session runs. */
    private static boolean aprsPassiveWanted(boolean useSquelch, boolean squelchOpen) {
        int mode = aprsPassiveMode;
        if (mode < 0) { loadAprsPassivePrefs(); mode = aprsPassiveMode; }
        if (mode <= 0) return false;
        if (currentChannelType != 1) return false;                       // analog FM only
        if (isSSTVMonitoringActive || isNOAAMonitoringActive || isWxMonitoringActive) return false;
        if (useSquelch && !squelchOpen) return false;
        return mode == 2 || aprsPassiveFlagged.contains(currentChannelNumber);
    }

    /** Loads passive_mode + the flagged channel set. Leaves -1 (retry later) when no Context is available yet. */
    private static void loadAprsPassivePrefs() {
        try {
            android.content.Context ctx = null;
            if (homeActivityRef != null) ctx = homeActivityRef.get();
            if (ctx == null && mLocalViewObject instanceof View) ctx = ((View) mLocalViewObject).getContext();
            if (ctx == null) return;
            android.content.SharedPreferences g = ctx.getSharedPreferences("dmrmod_aprs_global", android.content.Context.MODE_PRIVATE);
            int m = g.getInt("passive_mode", 2);
            java.util.HashSet<Integer> set = new java.util.HashSet<>(APRSDatabase.getInstance(ctx).getEnabledChannels());
            aprsPassiveFlagged = set;
            aprsPassiveMode = m;
            XposedBridge.log(TAG + ": [aprs] passive decode mode=" + m + " flagged channels=" + set);
        } catch (Throwable t) {
            aprsPassiveMode = 0;
            XposedBridge.log(TAG + ": [aprs] passive prefs load failed (off): " + t.getMessage());
        }
    }

    private static void bufferAudioForAPRS(byte[] audioData, int length) {
        try {
            // (per-chunk "called"/"buffer size" logs removed 2026-10-17 — passive mode would log every 64 ms)
            
            // Convert bytes to shorts (16-bit PCM Little Endian)
            for (int i = 0; i < length - 1; i += 2) {
                short sample = (short) ((audioData[i + 1] << 8) | (audioData[i] & 0xFF));
                aprsAudioBuffer.add(sample);
            }
            
            // Process when buffer reaches 2 seconds (32000 samples at 16kHz)
            if (aprsAudioBuffer.size() >= APRS_BUFFER_SIZE) {
                processAPRSBuffer();
            }
            
        } catch (Exception e) {
            XposedBridge.log(TAG + ": Error buffering APRS audio: " + e.getMessage());
        }
    }
    
    /**
     * Process buffered audio for APRS decoding
     */
    private static void processAPRSBuffer() {
        if (aprsAudioBuffer.isEmpty()) {
            return;
        }
        
        // Allow processing even without UI context (for autonomous operation)
        // Context is only needed for displaying results in UI
        
        try {
            XposedBridge.log(TAG + ": Processing APRS buffer (" + aprsAudioBuffer.size() + " samples)");
            
            // Convert List<Short> to short array, prepending the last 1 s of the previous buffer so
            // a frame that straddles the 2 s chunk boundary is whole in one of the two windows
            // (APRSReceiver drops the duplicate when a frame lands in both). A stale tail (gap of
            // more than 5 s since the last window) is discarded.
            long nowMs = System.currentTimeMillis();
            if (nowMs - aprsLastProcessMs > 5000) aprsOverlapTail = null;
            aprsLastProcessMs = nowMs;
            int cur = aprsAudioBuffer.size();
            short[] tail = aprsOverlapTail;
            int tailLen = tail != null ? tail.length : 0;
            short[] audioSamples = new short[tailLen + cur];
            if (tailLen > 0) System.arraycopy(tail, 0, audioSamples, 0, tailLen);
            for (int i = 0; i < cur; i++) audioSamples[tailLen + i] = aprsAudioBuffer.get(i);
            int keep = Math.min(cur, APRS_OVERLAP_SAMPLES);
            aprsOverlapTail = new short[keep];
            System.arraycopy(audioSamples, audioSamples.length - keep, aprsOverlapTail, 0, keep);
            
            // ★ RESAMPLE 16kHz → 48kHz (DMR radio audio is 16kHz, APRS decoder expects 48kHz)
            short[] resampled = resample16to48(audioSamples);
            XposedBridge.log(TAG + ": Resampled audio from " + audioSamples.length + " to " + resampled.length + " samples");
            
            // Get current channel (use currentChannelNumber if available)
            int channelNumber = currentChannelNumber > 0 ? currentChannelNumber : 0;
            
            // Process audio in background thread
            final short[] samples = resampled;
            final int channel = channelNumber;
            new Thread(new Runnable() {
                @Override
                public void run() {
                    try {
                        // Try to get context if available, otherwise just decode and log
                        Context context = null;
                        if (mLocalViewObject instanceof View) {
                            context = ((View) mLocalViewObject).getContext();
                        }
                        if (context == null && homeActivityRef != null) context = homeActivityRef.get();
                        
                        if (context != null) {
                            APRSReceiver receiver = APRSReceiver.getInstance(context);
                            XposedBridge.log(TAG + ": Calling APRSReceiver.processAudio()");
                            receiver.processAudio(samples, channel);
                        } else {
                            // No context - just decode and log results
                            XposedBridge.log(TAG + ": No context available - decoding without UI display");
                            AFSKDecoder.decode(samples);  // This will log results
                        }
                    } catch (Exception e) {
                        XposedBridge.log(TAG + ": Error processing APRS audio: " + e.getMessage());
                        e.printStackTrace();
                    }
                }
            }).start();
            
            // Keep last 0.5 seconds for overlap (8000 samples at 16kHz)
            int keepSamples = 8000;
            if (aprsAudioBuffer.size() > keepSamples) {
                List<Short> newBuffer = new ArrayList<>(aprsAudioBuffer.subList(
                        aprsAudioBuffer.size() - keepSamples, aprsAudioBuffer.size()));
                aprsAudioBuffer.clear();
                aprsAudioBuffer.addAll(newBuffer);
            }
            
        } catch (Exception e) {
            XposedBridge.log(TAG + ": Error processing APRS buffer: " + e.getMessage());
            e.printStackTrace();
        }
    }
    
    /**
     * Resample audio from 16 kHz to 48 kHz using linear interpolation
     * DMR radio sends 16 kHz audio, but APRS decoder expects 48 kHz
     */
    private static short[] resample16to48(short[] input) {
        // 48kHz / 16kHz = 3x samples
        int outputLength = input.length * 3;
        short[] output = new short[outputLength];
        
        for (int i = 0; i < input.length - 1; i++) {
            // Original sample at position i*3
            output[i * 3] = input[i];
            
            // Interpolate 2 samples between input[i] and input[i+1]
            int sample1 = input[i];
            int sample2 = input[i + 1];
            
            output[i * 3 + 1] = (short) ((2 * sample1 + sample2) / 3);
            output[i * 3 + 2] = (short) ((sample1 + 2 * sample2) / 3);
        }
        
        // Last sample
        output[outputLength - 3] = input[input.length - 1];
        output[outputLength - 2] = input[input.length - 1];
        output[outputLength - 1] = input[input.length - 1];
        
        return output;
    }
    
    /**
     * Process transcription using TensorFlow Lite
     * Called when transmission ends (RECEIVE_STOP)
     */
    /**
     * Process audio transcription in-process via Google Cloud Speech-to-Text ({@link TranscriptionClient}).
     */
    /** True when transcription should use the on-device live-caption engine (default when the companion app is installed). */
    private static boolean captionEngineVosk(android.content.Context ctx) {
        try {
            if (captionCompanionInstalled < 0) {
                try { ctx.getPackageManager().getPackageInfo(CAPTION_PKG, 0); captionCompanionInstalled = 1; }
                catch (Throwable t) { captionCompanionInstalled = 0; }
            }
            String engine = ctx.getSharedPreferences("dmrmod_transcription", android.content.Context.MODE_PRIVATE).getString("engine", "vosk");
            return "vosk".equals(engine) && captionCompanionInstalled == 1;
        } catch (Throwable t) { return false; }
    }

    private static final String[] CAPTION_MODELS = {
        "vosk-model-small-en-us-0.15", "vosk-model-en-us-0.22-lgraph", "vosk-model-en-us-0.22", "vosk-model-en-us-0.42-gigaspeech" };
    private static final String[] CAPTION_MODEL_LABELS = {
        "Small \u2014 40 MB, fastest, least accurate",
        "Better \u2014 125 MB, good balance (default)",
        "Best \u2014 1.8 GB, full-size English model",
        "Max \u2014 2.3 GB, GigaSpeech-trained, most accurate" };

    /** Ask the companion to use a given Vosk model (downloads it on first use). */
    private static void captionSetModel(android.content.Context ctx, String model) {
        try {
            ctx.getSharedPreferences("dmrmod_transcription", android.content.Context.MODE_PRIVATE).edit().putString("model", model).apply();
            android.content.Intent svc = new android.content.Intent();
            svc.setComponent(new android.content.ComponentName(CAPTION_PKG, CAPTION_SERVICE));
            svc.putExtra("model", model);
            if (android.os.Build.VERSION.SDK_INT >= 26) ctx.startForegroundService(svc); else ctx.startService(svc);
            XposedBridge.log(TAG + ": [caption] model -> " + model);
        } catch (Throwable t) { XposedBridge.log(TAG + ": [caption] set model: " + t.getMessage()); }
    }

    private static void showCaptionModelDialog(final android.content.Context ctx) {
        final android.content.SharedPreferences tp = ctx.getSharedPreferences("dmrmod_transcription", android.content.Context.MODE_PRIVATE);
        String cur = tp.getString("model", CAPTION_MODELS[1]);
        int sel = 1;
        for (int i = 0; i < CAPTION_MODELS.length; i++) if (CAPTION_MODELS[i].equals(cur)) sel = i;
        new AlertDialog.Builder(ctx)
            .setTitle("Live-caption model")
            .setSingleChoiceItems(CAPTION_MODEL_LABELS, sel, null)
            .setPositiveButton("Use", new DialogInterface.OnClickListener() {
                @Override public void onClick(DialogInterface d, int w) {
                    int i = ((AlertDialog) d).getListView().getCheckedItemPosition();
                    if (i < 0 || i >= CAPTION_MODELS.length) i = 1;
                    captionSetModel(ctx, CAPTION_MODELS[i]);
                    Toast.makeText(ctx, "Switching to " + CAPTION_MODEL_LABELS[i].split(" \u2014 ")[0] + " model; it downloads once (watch the Live captions notification)", Toast.LENGTH_LONG).show();
                }
            })
            .setNegativeButton("Cancel", null)
            .show();
    }

    private static String[] loadCaptionKeywords(android.content.Context ctx) {
        String[] k = captionKeywords;
        if (k != null) return k;
        java.util.List<String> out = new java.util.ArrayList<String>();
        try {
            String raw = ctx.getSharedPreferences("dmrmod_transcription", android.content.Context.MODE_PRIVATE).getString("keywords", "");
            for (String w : raw.split("[,\\n]")) { w = w.trim().toLowerCase(java.util.Locale.US); if (!w.isEmpty()) out.add(w); }
        } catch (Throwable ignored) { }
        k = out.toArray(new String[0]);
        captionKeywords = k;
        return k;
    }

    /**
     * Keyword alert: a finished caption sentence (either engine) that contains one of the user's words
     * vibrates, speaks and writes a history line. Whole-word, case-insensitive, 15 s per-word hold-off.
     */
    static void checkCaptionKeywords(final android.content.Context ctx, String sentence) {
        try {
            if (sentence == null || sentence.isEmpty()) return;
            String[] words = loadCaptionKeywords(ctx);
            if (words.length == 0) return;
            String low = " " + sentence.toLowerCase(java.util.Locale.US).replaceAll("[^a-z0-9' ]+", " ") + " ";
            String hit = null;
            long now = System.currentTimeMillis();
            for (String w : words) {
                if (!low.contains(" " + w + " ")) continue;
                synchronized (keywordLastHit) {
                    Long last = keywordLastHit.get(w);
                    if (last != null && now - last < 15000) continue;
                    keywordLastHit.put(w, now);
                }
                hit = w; break;
            }
            if (hit == null) return;
            final String word = hit;
            XposedBridge.log(TAG + ": [keyword] \"" + word + "\" in: " + sentence);
            try {
                android.os.Vibrator vib = (android.os.Vibrator) ctx.getSystemService(android.content.Context.VIBRATOR_SERVICE);
                if (vib != null) {
                    long[] pat = { 0, 250, 120, 250, 120, 400 };
                    if (android.os.Build.VERSION.SDK_INT >= 26) vib.vibrate(android.os.VibrationEffect.createWaveform(pat, -1)); else vib.vibrate(pat, -1);
                }
            } catch (Throwable t) { XposedBridge.log(TAG + ": [keyword] vibrate: " + t.getMessage()); }
            MainHook mi = moduleInstance;
            if (mi != null) mi.updateActivityIndicator("🔔 Keyword \"" + word + "\"");
            final String chan = currentChannelName != null && !currentChannelName.isEmpty() ? currentChannelName : ("channel " + currentChannelNumber);
            new android.os.Handler(android.os.Looper.getMainLooper()).post(new Runnable() { @Override public void run() {
                try { Toast.makeText(ctx, "🔔 Keyword \"" + word + "\" heard on " + chan, Toast.LENGTH_LONG).show(); } catch (Throwable ignored) { }
            } });
            voiceSay(ctx, "Keyword " + word + " on " + chan);
        } catch (Throwable t) { XposedBridge.log(TAG + ": [keyword] " + t.getMessage()); }
    }

    private static void showKeywordAlertDialog(final Activity activity) {
        try {
            final android.content.SharedPreferences tp = activity.getSharedPreferences("dmrmod_transcription", android.content.Context.MODE_PRIVATE);
            final android.widget.EditText et = new android.widget.EditText(activity);
            et.setHint("e.g. emergency, mayday, your name, your town");
            et.setText(tp.getString("keywords", ""));
            et.setMinLines(3);
            et.setInputType(android.text.InputType.TYPE_CLASS_TEXT | android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE | android.text.InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);
            android.widget.LinearLayout box = new android.widget.LinearLayout(activity);
            box.setOrientation(android.widget.LinearLayout.VERTICAL);
            int pad = (int) (20 * activity.getResources().getDisplayMetrics().density);
            box.setPadding(pad, pad / 2, pad, 0);
            android.widget.TextView help = new android.widget.TextView(activity);
            help.setText("Words or short phrases, separated by commas. While TXT (captions) is on, any transmission whose caption contains one of them vibrates the phone, speaks the word (if Voice announcements are on) and writes a 🔔 line to the channel history. Matching is whole-word and ignores case.");
            help.setTextSize(13);
            box.addView(help);
            box.addView(et);
            new AlertDialog.Builder(activity)
                .setTitle("🔔 Caption keyword alerts")
                .setView(box)
                .setPositiveButton("Save", new DialogInterface.OnClickListener() {
                    @Override public void onClick(DialogInterface d, int w) {
                        String v = et.getText().toString().trim();
                        tp.edit().putString("keywords", v).apply();
                        captionKeywords = null;
                        int n = loadCaptionKeywords(activity).length;
                        Toast.makeText(activity, n == 0 ? "Keyword alerts off (no words)" : n + " keyword" + (n == 1 ? "" : "s") + " armed" + (isTranscriptionEnabled ? "" : " \u2014 turn TXT on to listen"), Toast.LENGTH_LONG).show();
                    }
                })
                .setNegativeButton("Cancel", null)
                .show();
        } catch (Throwable t) { XposedBridge.log(TAG + ": keyword dialog: " + t.getMessage()); }
    }

    private static String captionPrefix() {
        if (currentChannelType == 0) {
            if (currentCallerName != null && !currentCallerName.isEmpty()) return currentCallerName + ": ";
            if (currentCallerDmrId > 0) return "ID " + currentCallerDmrId + ": ";
        }
        return "";
    }

    private static void showLiveCaption(final String text) {
        try {
            final LinearLayout container = transcriptionMessagesContainer;
            if (container == null) return;
            container.post(new Runnable() {
                @Override public void run() {
                    try {
                        if (transcriptionBox != null) transcriptionBox.setVisibility(View.VISIBLE); if (circuitBoardView != null) circuitBoardView.barsCompact = true;
                        TextView tv = liveCaptionView;
                        if (tv == null || tv.getParent() != container) {
                            tv = new TextView(container.getContext());
                            tv.setTextColor(0xFF00E5FF);
                            tv.setTextSize(12);
                            tv.setTypeface(null, android.graphics.Typeface.ITALIC);
                            tv.setPadding(0, 2, 0, 2);
                            container.addView(tv);
                            liveCaptionView = tv;
                        }
                        tv.setText(text);
                        if (transcriptionScrollView != null) transcriptionScrollView.post(new Runnable() {
                            @Override public void run() { transcriptionScrollView.fullScroll(View.FOCUS_DOWN); }
                        });
                    } catch (Throwable ignore) { }
                }
            });
        } catch (Throwable ignore) { }
    }

    private static void removeLiveCaption() {
        final LinearLayout container = transcriptionMessagesContainer;
        final TextView tv = liveCaptionView;
        liveCaptionView = null;
        if (container == null || tv == null) return;
        container.post(new Runnable() { @Override public void run() { try { container.removeView(tv); } catch (Throwable ignore) { } } });
    }

    /** RECEIVE_START: start the companion service if needed, connect, and stream until captionStop(). */
    private static void captionStart(final android.content.Context ctxIn) {
        if (captionActive) return;
        captionActive = true;
        synchronized (captionFinalText) { captionFinalText.setLength(0); }
        final android.content.Context ctx = ctxIn.getApplicationContext() != null ? ctxIn.getApplicationContext() : ctxIn;
        final java.util.concurrent.LinkedBlockingQueue<byte[]> q = new java.util.concurrent.LinkedBlockingQueue<>();
        captionQueue = q;
        new Thread(new Runnable() { @Override public void run() {
            java.net.Socket sock = null;
            try {
                try {
                    android.content.Intent svc = new android.content.Intent();
                    svc.setComponent(new android.content.ComponentName(CAPTION_PKG, CAPTION_SERVICE));
                    if (android.os.Build.VERSION.SDK_INT >= 26) ctx.startForegroundService(svc); else ctx.startService(svc);
                } catch (Throwable t) { XposedBridge.log(TAG + ": [caption] start service: " + t.getMessage()); }
                for (int i = 0; i < 16 && captionActive; i++) {
                    try { sock = new java.net.Socket(); sock.connect(new java.net.InetSocketAddress("127.0.0.1", CAPTION_PORT), 500); break; }
                    catch (Throwable t) { sock = null; Thread.sleep(250); }
                }
                if (sock == null) {
                    showLiveCaption("⏳ Captions: companion service not reachable (starting?)");
                    captionActive = false; captionQueue = null;
                    return;
                }
                captionSocket = sock;
                sock.setTcpNoDelay(true);
                final java.io.OutputStream out = sock.getOutputStream();
                final java.net.Socket fs = sock;
                // writer: drain the audio queue; an empty array = end of utterance
                Thread writer = new Thread(new Runnable() { @Override public void run() {
                    try {
                        while (true) {
                            byte[] b = q.poll(CAPTION_PAUSE_MS, java.util.concurrent.TimeUnit.MILLISECONDS);
                            if (b == null || b.length == 0) { fs.shutdownOutput(); break; }   // pause or RECEIVE_STOP
                            out.write(b); out.flush();
                        }
                    } catch (Throwable t) { XposedBridge.log(TAG + ": [caption] writer: " + t.getMessage()); }
                } }, "dmrmod-caption-writer");
                writer.setDaemon(true); writer.start();
                // reader: JSON lines from the recognizer
                java.io.BufferedReader in = new java.io.BufferedReader(new java.io.InputStreamReader(sock.getInputStream(), "UTF-8"));
                String line;
                while ((line = in.readLine()) != null) {
                    try {
                        org.json.JSONObject o = new org.json.JSONObject(line);
                        if (o.has("status")) {
                            String st = o.optString("status");
                            if (!"ready".equals(st)) { showLiveCaption("⏳ Captions: " + st); }
                            continue;
                        }
                        if (o.has("partial")) {
                            String ptxt = o.optString("partial").trim();
                            if (!ptxt.isEmpty()) showLiveCaption("🎙️ " + ptxt + " \u2026");
                        } else if (o.has("text")) {
                            String t = o.optString("text").trim();
                            if (!t.isEmpty()) {
                                synchronized (captionFinalText) { if (captionFinalText.length() > 0) captionFinalText.append(' '); captionFinalText.append(t); }
                                updateTranscriptionDisplay(captionPrefix() + t);   // finished sentence scrolls up as a normal line
                                checkCaptionKeywords(ctx, t);
                                showLiveCaption("🎙️ \u2026");
                            }
                        }
                    } catch (Throwable t) { XposedBridge.log(TAG + ": [caption] line: " + t.getMessage()); }
                }
            } catch (Throwable t) {
                XposedBridge.log(TAG + ": [caption] " + t.getMessage());
            } finally {
                try { if (sock != null) sock.close(); } catch (Throwable ignore) { }
                captionSocket = null; captionQueue = null; captionActive = false;
                String text; synchronized (captionFinalText) { text = captionFinalText.toString().trim(); }
                removeLiveCaption();
                captionLastEndMs = System.currentTimeMillis();
                if (!text.isEmpty()) {
                    currentTranscription = text;
                    persistTranscription(ctx, text);
                    XposedBridge.log(TAG + ": [caption] final: " + text);
                }
            }
        } }, "dmrmod-caption").start();
    }

    /** 8 kHz stereo (L==R) frames -> 16 kHz mono PCM (linear interpolation) for the recognizer. */
    private static void captionFeed(byte[] data, int length) {
        try {
            java.util.concurrent.LinkedBlockingQueue<byte[]> q = captionQueue;
            if (q == null || q.size() > 400) return;
            int n = length / 4;
            if (n < 2) return;
            byte[] out = new byte[n * 4];
            int prev = (short) ((data[1] << 8) | (data[0] & 0xFF));
            for (int i = 0; i < n; i++) {
                int cur = (short) ((data[4 * i + 1] << 8) | (data[4 * i] & 0xFF));
                int mid = (prev + cur) >> 1;
                out[4 * i] = (byte) mid; out[4 * i + 1] = (byte) (mid >> 8);
                out[4 * i + 2] = (byte) cur; out[4 * i + 3] = (byte) (cur >> 8);
                prev = cur;
            }
            q.offer(out);
        } catch (Throwable ignore) { }
    }

    /** RECEIVE_STOP: end the utterance; the reader thread finishes with the final result. */
    private static void captionStop() {
        java.util.concurrent.LinkedBlockingQueue<byte[]> q = captionQueue;
        if (q != null) q.offer(new byte[0]);
    }

    private static void processTranscription(Context context) {
        if (!isTranscriptionEnabled || audioBuffer.isEmpty()) {
            return;
        }
        
        XposedBridge.log(TAG + ": Processing transcription for " + audioBuffer.size() + " audio samples");

        final String apiKey = readApiKeyFromFile();
        if (TranscriptionClient.isPlaceholderKey(apiKey)) {
            XposedBridge.log(TAG + ": Transcription key not configured");
            currentTranscription = "[API key not configured - long-press TXT to set it]";
            updateTranscriptionDisplay(currentTranscription);
            audioBuffer.clear();
            return;
        }

        // Process in background thread to avoid blocking
        new Thread(new Runnable() {
            @Override
            public void run() {
                try {
                    // Convert List<Short> to byte array (16-bit PCM Little Endian)
                    // Cache size to prevent race condition (audioBuffer grows during iteration)
                    int bufferSize = audioBuffer.size();
                    byte[] pcmBytes = new byte[bufferSize * 2];
                    for (int i = 0; i < bufferSize; i++) {
                        short sample = audioBuffer.get(i);
                        pcmBytes[i * 2] = (byte) (sample & 0xFF);          // Low byte
                        pcmBytes[i * 2 + 1] = (byte) ((sample >> 8) & 0xFF); // High byte
                    }
                    
                    XposedBridge.log(TAG + ": Transcribing " + pcmBytes.length + " bytes via Google Cloud STT");

                    // In-process call (Google Cloud Speech-to-Text REST)
                    String result = TranscriptionClient.transcribe(pcmBytes, 16000, apiKey);
                    
                    if (result != null && !result.trim().isEmpty()) {
                        currentTranscription = result;
                        XposedBridge.log(TAG + ": ✅ Transcription: " + result);
                        persistTranscription(context, result);
                    } else {
                        currentTranscription = "[No speech detected]";
                        XposedBridge.log(TAG + ": No speech detected in audio");
                    }
                    
                    // Format display message with DMR ID or contact name (digital only)
                    // Use saved caller info since currentCallerDmrId is cleared after RECEIVE_STOP
                    String displayMessage = currentTranscription;
                    XposedBridge.log(TAG + ": Formatting transcription display - channelType=" + savedChannelTypeForTranscription + ", callerDmrId=" + savedCallerDmrIdForTranscription + ", callerName=" + savedCallerNameForTranscription);
                    
                    if (savedChannelTypeForTranscription == 0) {  // Digital/DMR only
                        if (savedCallerNameForTranscription != null && !savedCallerNameForTranscription.isEmpty()) {
                            displayMessage = savedCallerNameForTranscription + ": " + currentTranscription;
                            XposedBridge.log(TAG + ": Display with contact name: " + displayMessage);
                        } else if (savedCallerDmrIdForTranscription > 0) {
                            displayMessage = "ID " + savedCallerDmrIdForTranscription + ": " + currentTranscription;
                            XposedBridge.log(TAG + ": Display with DMR ID: " + displayMessage);
                        } else {
                            XposedBridge.log(TAG + ": No caller info available for display");
                        }
                    } else {
                        XposedBridge.log(TAG + ": Analog channel - no caller info displayed");
                    }
                    
                    updateTranscriptionDisplay(displayMessage);
                    
                    // Save to text file (always save, independent of recording)
                    saveTranscriptionToFile(currentTranscription, null);
                    
                } catch (Exception e) {
                    XposedBridge.log(TAG + ": ❌ Error processing transcription: " + e.getMessage());
                    e.printStackTrace();
                    
                    currentTranscription = "[Error: " + e.getMessage() + "]";
                    updateTranscriptionDisplay(currentTranscription);
                } finally {
                    // Clear buffer for next transmission
                    audioBuffer.clear();
                }
            }
        }).start();
    }
    
    /**
     * Read API key from Download/DMR/api_key.txt
     */
    private static String readApiKeyFromFile() {
        try {
            java.io.File downloadDir = Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS);
            java.io.File dmrDir = new java.io.File(downloadDir, "DMR");
            java.io.File apiKeyFile = new java.io.File(dmrDir, "api_key.txt");
            
            if (apiKeyFile.exists()) {
                BufferedReader reader = new BufferedReader(new FileReader(apiKeyFile));
                String key = reader.readLine();
                reader.close();
                
                if (key != null) {
                    return key.trim();
                }
            }
        } catch (Exception e) {
            XposedBridge.log(TAG + ": Error reading API key: " + e.getMessage());
        }
        return null;
    }
    
    /**
     * Write API key to Download/DMR/api_key.txt
     */
    private static boolean writeApiKeyToFile(String apiKey) {
        try {
            java.io.File downloadDir = Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS);
            java.io.File dmrDir = new java.io.File(downloadDir, "DMR");
            dmrDir.mkdirs();
            java.io.File apiKeyFile = new java.io.File(dmrDir, "api_key.txt");
            
            FileWriter writer = new FileWriter(apiKeyFile);
            writer.write(apiKey.trim() + "\n");
            writer.write("\n");
            writer.write("# Google Cloud Speech-to-Text API Key\n");
            writer.write("# Get your API key from: https://console.cloud.google.com\n");
            writer.write("# Enable 'Cloud Speech-to-Text API'\n");
            writer.write("# Free tier: 60 minutes/month\n");
            writer.close();
            
            XposedBridge.log(TAG + ": API key saved to " + apiKeyFile.getAbsolutePath());
            return true;
        } catch (Exception e) {
            XposedBridge.log(TAG + ": Error writing API key: " + e.getMessage());
            return false;
        }
    }
    
